const ico = (name) => {
  const t = document.createElement("template");
  const tech = TECH_ICONS[name];
  t.innerHTML = tech
    ? `<svg class="ico tech${tech[0] ? " tech-color" : ""}" viewBox="-12 -12 152 152" aria-hidden="true" data-tech="${name}"${tech[0] ? ` style="--brand:${tech[0]}"` : ""}>${tech[1].map((d) => `<path d="${d}" fill="currentColor"/>`).join("")}</svg>`
    : `<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  return t.content.firstChild;
};
const setLabel = (el, name, text) => el.replaceChildren(ico(name), text);
const ib = (props, name, ...kids) => h("button", props, ico(name), ...kids);
for (const el of $$("[data-icon]")) el.prepend(ico(el.dataset.icon));

const wsURL = (path) => `${location.protocol === "https:" ? "wss" : "ws"}://${location.host}${path}`;
