let todoChatId = null;
async function loadTodoChat() {
  const id = state.detail;
  // Reopening the todo whose reply is still streaming keeps it on screen.
  // The events file only grows, so the worker's events from while it was closed are those past ours.
  if (todoChatId === id && todoChat.busy) {
    const events = await api("GET", `/api/todos/${id}/events`);
    if (state.detail === id && worker.id === id) events.slice(worker.events.length).forEach((e) => addWorkerEvent(id, e));
    return todoChat.toEnd();
  }
  todoChatId = id;
  worker.id = null;
  worker.events = worker.live = [];
  todoChat.reset();
  const [saved, events] = await Promise.all([api("GET", `/api/todos/${id}/chat`), api("GET", `/api/todos/${id}/events`)]);
  if (state.detail !== id) return;
  // Events that streamed in while loading, unless the load has them already.
  const key = (e) => `${e.at}|${e.kind}|${e.id || ""}`;
  const seen = new Set(events.map(key));
  worker.id = id;
  worker.events = [...events, ...worker.live.filter((e) => !seen.has(key(e)))];
  worker.live = [];
  if (!todoChat.history.length && !todoChat.busy) todoChat.reset(saved);
}

// ------------------------------------------------------------------ task timeline
// The task chat's log is the task's timeline: the worker's runs (labelled
// Agent) among the side chat's turns (labelled Chat), in time order. Only the
// worker's events are kept here; the chat keeps its own history.
const worker = { id: null, events: [], live: [], cur: null, tools: new Map(), phase: null };

// A step Dash runs itself (setup, tests): a spinner and a timer while it runs,
// its output underneath, and how it went once it ends.
function phaseBlock(label, cmd, since) {
  const spin = h("span", { class: "act-spin", "aria-hidden": "true" });
  const name = h("b", {}, label);
  const time = h("span", { class: "act-time", "data-since": String(since) }, duration(Date.now() - since));
  const log = h("pre", { class: "log tl-log", hidden: true });
  const el = h("details", { class: "tl-phase running", open: true }, h("summary", {}, spin, name, h("code", {}, cmd), time), log);
  return { el, spin, name, time, log, since };
}

// endPhase closes the open phase at event e. A test result line becomes its
// header (and true is returned, as it says nothing more); any other event
// means the phase is over too.
function endPhase(e) {
  const p = worker.phase;
  if (!p) return false;
  worker.phase = null;
  const text = e.kind === "status" ? e.text || "" : "";
  const res = /^([✔✖]) (tests (passed|failed)[^]*)/.exec(text);
  const cls = res ? (res[1] === "✔" ? "pass" : "fail") : e.kind === "run_end" && e.is_error ? "stopped" : "done";
  p.el.classList.replace("running", cls);
  p.spin.replaceWith(h("span", { class: "phase-mark", "aria-hidden": "true" }, { pass: "✓", fail: "✗", stopped: "■", done: "✓" }[cls]));
  delete p.time.dataset.since;
  if (res) {
    p.name.textContent = res[2][0].toUpperCase() + res[2].slice(1);
    p.time.remove(); // the line has the duration
  } else {
    p.time.textContent = duration((Date.parse(e.at) || Date.now()) - p.since);
    if (cls === "stopped") p.name.textContent += " (stopped)";
  }
  if (cls === "pass" || cls === "done") p.el.open = false; // the output matters when it failed
  return !!res;
}

const clock = (iso) => new Date(iso).toLocaleTimeString(timeLocale, { hour: "2-digit", minute: "2-digit" });

// timeline merges a saved chat's message nodes with the worker's events.
function timeline(nodes, saved) {
  const at = (iso) => (iso ? Date.parse(iso) : Infinity); // chats from before timestamps go last
  const items = [
    ...saved.map((m, i) => ({ at: at(m.at), i, node: nodes[i] })),
    ...worker.events.map((e, i) => ({ at: at(e.at), i: saved.length + i, ev: e })),
  ].sort((a, b) => a.at - b.at || a.i - b.i);
  const frag = document.createDocumentFragment();
  worker.cur = null;
  worker.phase = null;
  worker.tools = new Map();
  for (const it of items) it.ev ? workerNode(frag, it.ev) : frag.append(it.node);
  return [...frag.childNodes];
}

// A worker event streamed in while its todo is open.
function addWorkerEvent(id, e) {
  if (worker.id !== id) { worker.live.push(e); return; } // still loading
  worker.events.push(e);
  const log = $("#d-chat-log"), sc = $(".detail-body");
  const stick = sc.scrollHeight - sc.scrollTop - sc.clientHeight < 120;
  $("#d-chat-empty").hidden = true;
  workerNode(log, e);
  if (stick && state.pane === "timeline") sc.scrollTop = sc.scrollHeight;
}

// workerNode adds one worker event to parent: text and tool calls go into the
// Agent turn at its end (or a new one), Dash's notes into a log block, and run
// boundaries become dividers.
function workerNode(parent, e) {
  // Live events animate in; a timeline being rebuilt (into a fragment) doesn't.
  const enter = (el) => parent.nodeType === Node.ELEMENT_NODE ? entering(el) : el;
  const last = (kind) => (worker.cur?.kind === kind && worker.cur.el === parent.lastElementChild ? worker.cur : null);
  const divider = (text, cls = "") => { worker.cur = null; parent.append(h("div", { class: `tl-divider ${cls}`, role: "separator" }, h("span", {}, text))); };
  switch (e.kind) {
    case "run_start":
      return divider(`Agent · ${e.text || "Started"} · ${clock(e.at)}`, "agent");
    case "run_end":
      // Whatever didn't report its end stopped with the run.
      endPhase(e);
      for (const t of worker.tools.values()) toolSettled(t);
      divider(`Agent ${e.is_error ? "stopped" : "finished"} · ${clock(e.at)}`, e.is_error ? "agent error" : "agent");
      if (e.is_error && e.text) parent.append(h("p", { class: "tl-error" }, e.text));
      return;
    case "prompt":
      worker.cur = null;
      return parent.append(enter(h("div", { class: "msg user to-agent" },
        ib({ type: "button", class: "btn small copy-raw", title: "Copy the raw markdown", onclick: attempt(() => copy(e.text || "", "Copied")) }, "copy", "Copy"),
        h("div", { class: "msg-from" }, "To agent"), h("div", { class: "md", innerHTML: renderMarkdown(e.text || "") }))));
    case "status": {
      const text = e.text || "";
      const start = /^▶ (setup|tests): ([^]*)/.exec(text);
      if (start) {
        endPhase(e);
        const p = worker.phase = phaseBlock(start[1] === "tests" ? "Running tests" : "Setting up the worktree", start[2], Date.parse(e.at));
        worker.cur = null;
        parent.append(p.el);
        return;
      }
      if (worker.phase && text.startsWith("│ ")) {
        const log = worker.phase.log, end = log.scrollHeight - log.scrollTop - log.clientHeight < 24;
        log.hidden = false;
        log.append(`${text.slice(2)}\n`);
        if (end) log.scrollTop = log.scrollHeight;
        return;
      }
      if (worker.phase && endPhase(e)) return; // the phase's own result line
      let cur = last("notes");
      if (!cur) { cur = worker.cur = { kind: "notes", el: h("pre", { class: "log tl-log" }) }; parent.append(cur.el); }
      cur.el.append(`${new Date(e.at).toLocaleTimeString(timeLocale)} ${e.text}\n`);
      return;
    }
    case "tool_result": {
      const t = worker.tools.get(e.id);
      if (t) toolResult(t, e);
      return;
    }
  }
  let cur = last("agent");
  if (!cur) {
    const reply = h("div", { class: "reply" });
    cur = worker.cur = { kind: "agent", el: enter(h("div", { class: "msg assistant agent" }, h("div", { class: "msg-from" }, "Agent"), reply)), reply, seg: "" };
    parent.append(cur.el);
  }
  switch (e.kind) {
    case "text":
      cur.seg += (cur.seg ? "\n\n" : "") + e.text;
      cur.reply.innerHTML = renderMarkdown(cur.seg);
      break;
    case "tool_use": {
      // Later text goes below the tool call, in a reply of its own.
      const t = toolCall(e.tool, e.input || {}, Date.parse(e.at) || Date.now());
      worker.tools.set(e.id, t);
      cur.el.append(enter(t.el));
      cur.reply = h("div", { class: "reply" });
      cur.el.append(cur.reply);
      cur.seg = "";
      break;
    }
    case "result":
      cur.el.append(e.is_error
        ? h("p", { class: "tl-error" }, e.text)
        : h("p", { class: "agent-meta" }, `${e.turns} ${e.turns === 1 ? "turn" : "turns"}${e.cost_usd ? ` · ≈$${e.cost_usd.toFixed(2)}` : ""}`));
      worker.cur = null;
      break;
  }
}

// ------------------------------------------------------------------ run: processes & terminal
// The Shell view's and the terminal preview's look.
const TERM_OPTS = {
  fontFamily: '"JetBrains Mono", ui-monospace, monospace', fontSize: 13, cursorBlink: true,
  theme: { background: "#0a0f17", foreground: "#e6ecf5", cursor: "#8aa4ff", selectionBackground: "#2a384d" },
};
const term = new window.Terminal(TERM_OPTS);
const fit = new window.FitAddon.FitAddon();
term.loadAddon(fit);
term.open($("#term"));
let termWS = null;
let attached = null;

const sendSize = () => termWS?.readyState === 1 && termWS.send(JSON.stringify({ type: "resize", cols: term.cols, rows: term.rows }));
function fitTerm() { if (state.view === "run") { try { fit.fit(); sendSize(); } catch {} } }
new ResizeObserver(fitTerm).observe($("#term"));
term.onData((data) => termWS?.readyState === 1 && termWS.send(JSON.stringify({ type: "input", data })));
// Ctrl-] leaves the terminal and returns to normal mode, like detaching in the TUI.
term.attachCustomKeyEventHandler((e) => {
  if (e.type === "keydown" && e.ctrlKey && e.key === "]") { term.blur(); setMode(); return false; }
  return true;
});

function attach(p) {
  renderShellNote();
  termWS?.close();
  attached = p.id;
  term.reset();
  // Piped (non-PTY) output has bare \n with no tty driver to add the \r.
  term.options.convertEol = p.kind !== "pty";
  requestAnimationFrame(fitTerm);
  termWS = new WebSocket(wsURL(on(here(), `/ws/proc/${p.id}`)));
  termWS.binaryType = "arraybuffer";
  termWS.onopen = sendSize;
  termWS.onmessage = (m) => {
    if (typeof m.data === "string") {
      const msg = JSON.parse(m.data);
      if (msg.type === "exit") term.write(`\r\n\x1b[90mProcess exited with code ${msg.code}\x1b[0m\r\n`);
    } else {
      term.write(new Uint8Array(m.data));
    }
  };
  renderProcs();
  if (p.kind === "pty") term.focus();
}

async function startProc(req, show = true) {
  const p = await api("POST", `/api/projects/${state.project.id}/processes`, { ...req, cols: term.cols, rows: term.rows });
  if (req.preset && !req.todo_id) quickStarted.set(`${req.kind}:${req.preset}`, p.id);
  // A runner's checkout of a hub project with uncommitted changes runs them.
  if (p.warning) toast(p.warning, { tone: "paused", head: "Uncommitted changes", ms: 9000 });
  if (!show) return loadProcs();
  closeDetail();
  attach(p);
  showView("run");
  if (p.url && !p.warning) toast(`Server starting at ${p.url}`);
}

// Why no terminal opens for project p (on a task's runner, with runnerID) on the hub,
// from its runners: only on the caller's own runner, and only one started with
// -hub-commands. "" when one may (or the runner hasn't said: it answers itself).
function shellBlocked(p = state.project, runnerID = "") {
  if (!p || p.prefix || !isHub()) return "";
  const online = state.runners.filter((r) => r.online && (runnerID ? r.id === runnerID : p.runners?.includes(r.id)));
  if (!online.length) return "";
  const mine = online.filter((r) => r.mine);
  if (!mine.length) {
    const names = online.map((r) => r.name).join(", ");
    return `Terminals open only on your own runner, and ${names} ${online.length > 1 ? "belong" : "belongs"} to another member. Its owner can open one, or link a runner of yours to ${p.name}.`;
  }
  if (mine.every((r) => r.reported && !r.reported.terminals)) {
    return `${mine.map((r) => r.name).join(", ")} doesn't open terminals for the hub. Start it with -hub-commands to allow it.`;
  }
  return "";
}

// openShell opens a terminal (req: todo_id, command), or says why it can't.
function openShell(req = {}, runnerID = "") {
  const why = shellBlocked(state.project, runnerID);
  if (why) throw new Error(why);
  return startProc({ kind: "pty", ...req });
}

// The Shell view is only a terminal: show the project's running shell, or open one.
// When the runner refuses, say why once instead of asking again with every update
// (until the runners or the project change).
let opening = false;
let shellRefused = null; // { pid, msg }
function renderShellNote(msg) {
  $("#shell-note").hidden = !msg;
  $("#term-wrap").hidden = !!msg;
  $("#shell-note-text").textContent = msg || "";
}
function ensureShell() {
  if (state.view !== "run" || !state.project || opening) return;
  if (attached && state.procs.some((p) => p.id === attached)) return renderShellNote();
  const blocked = shellBlocked(); // another member's shell is theirs: the runner won't attach it either
  const pty = !blocked && state.procs.filter((p) => p.kind === "pty" && p.running && inMain(p))
    .reduce((a, b) => (!a || b.started_at > a.started_at ? b : a), null);
  if (pty) { renderShellNote(); return attach(pty); }
  const pid = state.project.id;
  const why = blocked || (shellRefused?.pid === pid ? shellRefused.msg : "");
  renderShellNote(why);
  if (why) return;
  opening = true;
  startProc({ kind: "pty" })
    .catch((e) => {
      shellRefused = { pid, msg: e.message || String(e) };
      if (state.project?.id === pid) renderShellNote(shellRefused.msg);
    })
    .finally(() => { opening = false; });
}

const runPreset = attempt(async (e) => {
  const spec = e.target.closest("[data-run]")?.dataset.run;
  if (!spec || !state.project) return;
  const [kind, preset] = spec.split(":");
  await startProc({ kind, preset }, preset !== "deploy");
});
// While a quick action runs, clicking it shows its output instead of starting it again;
// a running server is stopped instead.
$("#quick-actions").addEventListener("click", attempt(async (e) => {
  const spec = e.target.closest("[data-run]")?.dataset.run;
  if (!spec) return; // Try has a handler of its own
  const proc = quickProc(spec);
  if (!proc?.running) return runPreset(e);
  if (spec === "web:run") {
    await api("DELETE", `/api/processes/${proc.id}`);
    toast("Stopping");
    return loadProcs();
  }
  closeDetail();
  attach(proc);
  showView("run");
}));

// The latest server/test/deploy process started from the project's own checkout (not a worktree).
const quickCmd = (spec) => ({ "web:run": state.project?.run_command, "task:test": state.project?.test_command, "task:deploy": state.project?.deploy_command })[spec];
// What a server or deploy command runs on, read from the command itself. First match wins; a rule without a label keeps the generic one.
const TECH_RULES = {
  "web:run": [
    [/\badb\s|gradlew.*install|installDebug|run[-:]android/, "android", "Run on Android"],
    [/xcodebuild|xcrun simctl|ios-deploy|run[-:]ios/, "apple", "Run on iOS"],
    [/\bflutter run\b/, "flutter", "Run Flutter app"],
    [/\bdocker[- ](compose )?(up|run)\b/, "docker"],
    [/\bnext\b/, "nextjs"],
    [/\bvite\b/, "vitejs"],
    [/\bbunx?\b/, "bun"],
    [/\b(npm|npx|pnpm|yarn)\b/, "nodejs"],
    [/\bgo run\b/, "go"],
    [/\bcargo run\b/, "rust"],
    [/\bdotnet run\b/, "dotnetcore"],
    [/manage\.py runserver/, "django"],
  ],
  "task:deploy": [
    [/\bvercel\b/, "vercel", "Deploy to Vercel"],
    [/\bnetlify\b/, "netlify", "Deploy to Netlify"],
    [/\bfirebase deploy\b/, "firebase", "Deploy to Firebase"],
    [/\bwrangler\b/, "cloudflare", "Deploy to Cloudflare"],
    [/\bheroku\b/, "heroku", "Deploy to Heroku"],
    [/\bkubectl\b/, "kubernetes", "Deploy to Kubernetes"],
    [/\bgcloud\b/, "googlecloud", "Deploy to GCP"],
    [/\b(aws|sam|cdk)\b/, "amazonwebservices", "Deploy to AWS"],
    [/\baz\b/, "azure", "Deploy to Azure"],
    [/\bdocker[- ](compose )?(up|run)\b/, "docker"],
  ],
};
const techFor = (spec) => {
  const cmd = quickCmd(spec);
  const hit = cmd && TECH_RULES[spec]?.find(([re]) => re.test(cmd));
  return hit ? { icon: hit[1], label: hit[2] } : {};
};
const quickPlainIcons = new Map($$(".quick-btn").map((b) => [b, b.querySelector("svg")]));
// A process running in the project's own checkout, not a task's worktree. Dash marks it
// (main); on a hub its dir is the runner's clone, never the hub's path. Processes from
// before Dash marked them go by their dir.
// A runner older than those marks lists its processes with its clone's dir: there, one
// that isn't a task's (no todo_id, not in a worktree) is taken to be in the checkout.
const inMain = (x) => x.main || (!x.preset && (x.dir === state.project?.path
  || (x.runner && !x.todo_id && !/\/worktrees\//.test(x.dir || ""))));
// The process each quick action last started from this page, by spec: found even when
// its runner doesn't mark it (see inMain).
const quickStarted = new Map();
function quickProc(spec) {
  // Found even with the command cleared, so a run still going can be viewed or stopped.
  const cmd = quickCmd(spec);
  const [kind, preset] = spec.split(":");
  const mine = quickStarted.get(spec);
  return state.procs.filter((x) => x.id === mine || (x.kind === kind && inMain(x) && (x.preset ? x.preset === preset : !!cmd && x.command === cmd)))
    .reduce((a, b) => (!a || b.started_at > a.started_at ? b : a), null);
}

function renderQuick() {
  renderTryButton();
  for (const [sel, verb, generic, noun, key] of [["#quick-server", "Serving", "Run", "server run", "R"], ["#quick-test", "Testing", "Run Tests", "test run", "T"], ["#quick-deploy", "Deploying", "Deploy", "deploy", "D"]]) {
    const btn = $(sel);
    const spec = btn.dataset.run;
    const proc = state.project ? quickProc(spec) : null;
    // Shown only with a command set, or while a run of it is still going.
    btn.hidden = !state.project || !(quickCmd(spec) || proc?.running);
    const ok = proc && !proc.running && proc.exit_code === 0 && sel !== "#quick-server";
    const bad = proc && !proc.running && proc.exit_code != null && proc.exit_code !== 0;
    const cut = proc && !proc.running && proc.exit_code == null;
    const stop = !!proc?.running && sel === "#quick-server";
    btn.classList.toggle("running", !!proc?.running && !stop);
    btn.classList.toggle("stop", stop);
    btn.classList.toggle("ok", !!ok);
    btn.classList.toggle("bad", !!bad);
    const tech = techFor(spec);
    const plain = quickPlainIcons.get(btn);
    const svg = btn.querySelector("svg");
    const icon = !stop && tech.icon;
    if (icon ? svg.dataset.tech !== icon : svg !== plain) svg.replaceWith(icon ? ico(icon) : plain);
    if (sel === "#quick-server") {
      const path = plain.querySelector("path");
      path.setAttribute("d", stop ? "M7 7h10v10H7z" : "M8 5.5v13l10.5-6.5z");
      path.setAttribute("fill", stop ? "currentColor" : "none");
    }
    const done = tech.label || generic;
    const secs = proc ? Math.max(0, Math.floor((Date.now() - new Date(proc.started_at)) / 1000)) : 0;
    const elapsed = `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, "0")}`;
    btn.querySelector("span").textContent = stop ? "Stop" : proc?.running ? `${verb} ${elapsed}` : done;
    btn.title = stop ? "Running — click to stop it"
      : proc?.running ? `${verb}… ${elapsed} — click to view output`
      : ok ? `Last ${noun} passed — click to run again`
      : bad ? `Last ${noun} failed (exit ${proc.exit_code}) — click to run again`
      : cut ? `Last ${noun} was interrupted by a Dash restart — click to run again`
      : `${done} (${key} on the Shell view)`;
  }
}
setInterval(() => { if ($(".quick-btn.running")) renderQuick(); }, 1000);

// ------------------------------------------------------------------ try: the project's CLI on a runner
// (tryState is declared with state, near the top: views render before this runs.)
// Try opens a terminal on the project itself (not a task): its preview_command,
// or a shell, in a throwaway worktree on a runner the user picks, at the tip of
// the default branch (fetched first) or a commit picked from its history. The
// project chat sits beside it (a tab of its own on phones), reads the terminal
// with read_try_terminal, and files what the user finds as issues or draft tasks.
function tryProject(p = state.project) { return !!p && p.preview_kind === "terminal" && !p.prefix; }
function shortSHA(sha) { return (sha || "").slice(0, 7); }
function trySend(msg) { if (tryState.ws?.readyState === 1) tryState.ws.send(JSON.stringify(msg)); }

async function loadTry() {
  const p = state.project;
  if (tryState.pid !== (p?.id || null)) {
    disconnectTry();
    Object.assign(tryState, { pid: p?.id || null, loaded: false, runners: [], disabled: "", session: null, runner: "", refused: null });
  }
  if (!tryProject(p)) { renderTryButton(); if (state.view === "try") renderTry(); return; }
  const st = await api("GET", `/api/projects/${p.id}/try`);
  if (state.project?.id !== p.id) return;
  Object.assign(tryState, { loaded: true, runners: st.runners || [], disabled: st.disabled || "", session: st.session || null });
  const ids = tryState.runners.map((r) => r.id);
  if (tryState.session) tryState.runner = tryState.session.runner_id;
  else if (!ids.includes(tryState.runner)) tryState.runner = st.default || "";
  renderTryButton();
  if (state.view === "try") renderTry();
}

function renderTryButton() {
  const btn = $("#quick-try"), why = $("#quick-try-why");
  const show = tryProject();
  const off = show && tryState.loaded && !tryState.runners.length && !tryState.session;
  btn.hidden = !show;
  btn.disabled = off;
  btn.classList.toggle("ok", !!tryState.session && tryState.session.state === "live");
  why.hidden = !off;
  why.textContent = off ? tryState.disabled : "";
  const s = tryState.session;
  btn.title = off ? tryState.disabled
    : s ? `Trying ${shortSHA(s.commit)} on ${s.runner}: open it`
      : "Try the project in a terminal on a runner, at main or an older commit";
}

function openTry() {
  if (!state.project) throw new Error("Pick a project first.");
  if (!tryProject()) throw new Error("Try is for CLI projects: set the preview to Terminal in the project's settings.");
  closeDetail();
  if (!desktop.matches) setMenu(false); // on phones Try is in the menu drawer
  showView("try");
}

// Entering the view reattaches to the running session, or starts one at the
// tip of the default branch when the runner is clear. Wide screens get the chat beside it.
async function enterTry() {
  renderTry();
  await loadTry();
  if (state.view !== "try") return;
  if (!tryState.session && tryState.runner && !tryState.starting) await startTry({ ref: "" });
  if (desktop.matches && !pane.open && state.project) toggleChatPane(true, "project");
}

function leaveTry() {
  disconnectTry();
}

async function startTry({ ref = tryState.session?.ref || "", runner = tryState.runner } = {}) {
  const p = state.project;
  if (!p) return;
  if (!runner) throw new Error(tryState.runners.length ? "Pick the runner to try it on." : tryState.disabled || "No runner can run Try for this project.");
  const name = tryState.runners.find((r) => r.id === runner)?.name || "the runner";
  const what = !ref ? `the latest ${p.default_branch || "main"}` : /^[0-9a-f]{7,40}$/i.test(ref) ? shortSHA(ref) : ref;
  tryState.starting = `${what} on ${name}`;
  tryState.runner = runner;
  disconnectTry();
  renderTry();
  try {
    const s = await api("POST", `/api/projects/${p.id}/try`, { runner, ref });
    if (state.project?.id !== p.id) return;
    Object.assign(tryState, { session: s, runner: s.runner_id, refused: null });
  } finally {
    tryState.starting = "";
    if (state.project?.id === p.id) { renderTry(); renderTryButton(); }
  }
}

async function stopTry() {
  const p = state.project;
  if (!p) return;
  disconnectTry();
  await api("DELETE", `/api/projects/${p.id}/try`);
  tryState.session = null;
  renderTry();
  renderTryButton();
  toast("Try stopped", { icon: "stop" });
}

function fitTryTerm() {
  if (!tryTerm || state.view !== "try" || $("#try-term-wrap").hidden) return;
  try { tryFit.fit(); trySend({ type: "resize", cols: tryTerm.cols, rows: tryTerm.rows }); } catch {}
}
function tryTermOnce() {
  if (tryTerm) return tryTerm;
  tryTerm = new window.Terminal(TERM_OPTS);
  tryFit = new window.FitAddon.FitAddon();
  tryTerm.loadAddon(tryFit);
  tryTerm.open($("#try-term"));
  new ResizeObserver(fitTryTerm).observe($("#try-term-wrap"));
  tryTerm.onData((data) => trySend({ type: "input", data }));
  tryTerm.attachCustomKeyEventHandler((e) => {
    if (e.type === "keydown" && e.ctrlKey && e.key === "]") { tryTerm.blur(); setMode(); return false; }
    return true;
  });
  return tryTerm;
}

function disconnectTry() {
  const ws = tryState.ws;
  tryState.ws = null;
  tryState.proc = null;
  ws?.close();
}

function connectTry(s) {
  disconnectTry();
  const term = tryTermOnce();
  term.reset();
  tryState.proc = s.process_id;
  tryState.got = false;
  const ws = new WebSocket(wsURL(s.terminal_url));
  ws.binaryType = "arraybuffer";
  ws.onopen = fitTryTerm;
  ws.onmessage = (m) => {
    tryState.got = true;
    if (typeof m.data === "string") {
      const msg = JSON.parse(m.data);
      if (msg.type === "exit") term.write(`\r\n\x1b[90mExited with code ${msg.code}\x1b[0m\r\n`);
    } else {
      term.write(new Uint8Array(m.data));
    }
  };
  ws.onclose = () => {
    if (tryState.ws !== ws) return; // closed on purpose
    tryState.ws = null;
    tryState.proc = null;
    // Never attached (the runner refused): don't keep trying the same one.
    if (!tryState.got) tryState.refused = s.process_id;
    loadTry().catch(() => renderTry()); // it exited, went idle, or the runner left
  };
  tryState.ws = ws;
  requestAnimationFrame(() => { fitTryTerm(); if (desktop.matches) term.focus(); });
}

function renderTry() {
  const p = state.project, s = tryState.session;
  const runs = [...tryState.runners];
  if (s && !runs.some((r) => r.id === s.runner_id)) runs.push({ id: s.runner_id, name: s.runner });
  const sel = $("#try-runner");
  sel.replaceChildren(...(tryState.runner ? [] : [h("option", { value: "" }, runs.length ? "Pick a runner…" : "No runner")]),
    ...runs.map((r) => h("option", { value: r.id }, r.name)));
  sel.value = tryState.runner;
  sel.disabled = runs.length <= 1 || !!tryState.starting;
  $("#try-runner-wrap").hidden = !runs.length;
  $("#try-sha").textContent = s ? shortSHA(s.commit) : p?.default_branch || "main";
  $("#try-subject").textContent = s ? s.subject : "latest";
  $("#try-commit").title = s ? `${s.commit.slice(0, 12)} · ${s.subject}${s.ref ? "" : ` (tip of ${s.branch})`} on ${s.runner}. Pick another commit` : "Pick the commit to try";
  $("#try-commit").disabled = !tryState.runner || !!tryState.starting;
  $("#try-restart").disabled = !tryState.runner || !!tryState.starting;
  $("#try-stop").disabled = !s || !!tryState.starting;
  $("#try-tab-term").setAttribute("aria-selected", "true");
  $("#try-tab-chat").setAttribute("aria-selected", "false");

  const attachable = !!s && s.state === "live" && !tryState.starting && tryState.refused !== s.process_id;
  // A session that exited keeps its last screen, with what to do next below it.
  const shown = attachable || (!!s && !tryState.starting && !!tryTerm && tryState.refused !== s.process_id && s.state === "crashed");
  $("#try-term-wrap").hidden = !shown;
  $("#try-keys").hidden = !attachable;
  if (attachable && tryState.proc !== s.process_id) connectTry(s);
  if (!attachable && tryState.ws) disconnectTry();

  const status = $("#try-status");
  const start = (label = "Start") => ib({ class: "btn primary", type: "button", onclick: attempt(() => startTry({ ref: s?.ref || "" })) }, "play", label);
  const say = (...kids) => { status.hidden = false; status.classList.toggle("strip", shown); status.replaceChildren(...kids); };
  status.hidden = true;
  if (!p) return say(h("strong", {}, "Pick a project"));
  if (!tryProject(p)) return say(h("strong", {}, "Try is for CLI projects"), h("p", { class: "hint" }, "Set the preview to Terminal in the project's settings: Try runs its preview command in a terminal on a runner."));
  if (tryState.starting) return say(h("div", { class: "spinner big", "aria-hidden": "true" }), h("strong", {}, "Checking out"), h("p", { class: "hint" }, tryState.starting));
  if (!tryState.loaded) return say(h("div", { class: "spinner big", "aria-hidden": "true" }));
  if (!runs.length) return say(h("strong", {}, "Try can't run"), h("p", { class: "hint" }, tryState.disabled));
  if (!tryState.runner) return say(h("strong", {}, "Pick a runner"), h("p", { class: "hint" }, "Try runs in a throwaway worktree on the runner you pick, never in its own checkout."));
  if (!s) return say(h("strong", {}, "Not running"), h("p", { class: "hint" }, "Try stops after 30 minutes without typing, and removes its worktree."), start());
  if (s.state === "crashed") return say(h("span", { class: "pv-err" }, `Exited${s.exit_code != null ? ` with code ${s.exit_code}` : ""}`), start("Start again"));
  if (tryState.refused === s.process_id) return say(h("strong", {}, "Couldn't attach to the terminal"), h("p", { class: "hint" }, `${s.runner} refused or went away.`),
    ib({ class: "btn", type: "button", onclick: () => { tryState.refused = null; renderTry(); } }, "reload", "Try again"));
}

// The commit picker: recent commits of the default branch from the runner's
// clone, searchable, or any hash, tag or branch typed in.
async function openTryCommits() {
  const p = state.project, runner = tryState.runner;
  if (!p || !runner) throw new Error("Pick the runner first.");
  const cur = tryState.session;
  const branch = p.default_branch || "main";
  const list = h("ul", { class: "try-commit-list", role: "listbox", "aria-label": "Commits" });
  const search = h("input", { type: "search", class: "try-commit-search", placeholder: "Search, or type a hash, tag or branch", "aria-label": "Search commits", autocomplete: "off", spellcheck: "false", autocapitalize: "off" });
  const note = h("p", { class: "hint try-commit-note" });
  const d = h("dialog", { class: "sheet try-commits-sheet", "aria-label": "Pick a commit" },
    h("form", { method: "dialog" },
      h("div", { class: "sheet-head" }, h("h2", {}, "Try a commit"), ib({ class: "icon-btn", value: "cancel", "aria-label": "Close" }, "x")),
      h("p", { class: "hint" }, `${branch} on ${tryState.runners.find((r) => r.id === runner)?.name || cur?.runner || "the runner"}`),
      search, list, note));
  d.addEventListener("close", () => d.remove());
  let shown = [];
  const pick = (ref) => { d.close(); startTry({ ref, runner }).catch(fail); };
  const row = (label, meta, ref, active, extra = null) => h("li", {},
    h("button", { type: "button", class: `try-commit-row${active ? " active" : ""}`, role: "option", "aria-selected": String(!!active), onclick: () => pick(ref) },
      extra, h("span", { class: "try-commit-text" }, h("span", { class: "try-commit-subject" }, label), meta ? h("span", { class: "try-commit-meta" }, meta) : null)));
  const render = (commits, q) => {
    shown = commits;
    const typed = q && !commits.some((c) => c.sha.startsWith(q.toLowerCase()) && commits.length === 1) && /^[\w./~^-]+$/.test(q) && !q.startsWith("-");
    list.replaceChildren(...[
      q ? null : row(`Latest ${branch}`, "fetched from origin when it starts", "", cur && !cur.ref, h("code", {}, branch)),
      typed ? row(`Check out “${q}”`, "a hash, tag or branch", q, false, h("code", {}, "ref")) : null,
      ...commits.map((c) => row(c.subject, `${c.author} · ${agoPhrase(c.date)}`, c.sha, cur?.ref && cur.commit === c.sha, h("code", {}, c.short))),
    ].filter(Boolean));
    note.textContent = commits.length >= 100 ? "Showing the latest 100 matches; search to narrow them." : !commits.length && q ? "No commit on the branch matches; you can still check out what you typed." : "";
  };
  let seq = 0;
  const load = async (q, fetch = false) => {
    const n = ++seq;
    const qs = new URLSearchParams({ runner });
    if (q) qs.set("q", q);
    if (fetch) qs.set("fetch", "1");
    const res = await api("GET", `/api/projects/${p.id}/try/commits?${qs}`);
    if (n !== seq) return;
    if (res.warning) note.textContent = res.warning;
    render(res.commits || [], q);
  };
  let timer;
  search.addEventListener("input", () => { clearTimeout(timer); timer = setTimeout(() => load(search.value.trim()).catch(fail), 250); });
  search.addEventListener("keydown", (e) => {
    if (e.key !== "Enter") return;
    e.preventDefault();
    const q = search.value.trim();
    if (shown.length === 1 && q) pick(shown[0].sha);
    else if (q) pick(q);
  });
  document.body.append(d);
  d.showModal();
  list.replaceChildren(h("li", { class: "try-commit-loading" }, h("div", { class: "spinner", "aria-hidden": "true" })));
  if (desktop.matches) search.focus();
  await load("", true);
}

$("#quick-try").addEventListener("click", attempt(openTry));
$("#try-commit").addEventListener("click", attempt(openTryCommits));
$("#try-restart").addEventListener("click", attempt(() => startTry({ ref: tryState.session?.ref || "" })));
$("#try-stop").addEventListener("click", attempt(stopTry));
$("#try-runner").addEventListener("change", attempt(async (e) => {
  const id = e.target.value;
  if (!id || id === tryState.session?.runner_id) { tryState.runner = id; return renderTry(); }
  await startTry({ ref: tryState.session?.ref || "", runner: id }); // switching runner replaces the session
}));
$("#try-chat").addEventListener("click", () => toggleChatPane(true, "project"));
$("#try-tab-chat").addEventListener("click", () => toggleChatPane(true, "project"));
$("#try-tab-term").addEventListener("click", () => { if (pane.open && !desktop.matches) toggleChatPane(false); });
$("#chat-try-back").addEventListener("click", () => toggleChatPane(false));
$$("#try-keys [data-key]").forEach((b) => {
  b.addEventListener("mousedown", (e) => e.preventDefault()); // the terminal keeps focus (and the keyboard stays up)
  b.addEventListener("click", () => {
    const k = b.dataset.key;
    trySend({ type: "input", data: PV_KEYS[k] ?? `\x1b${tryTerm?.modes?.applicationCursorKeysMode ? "O" : "["}${PV_ARROWS[k]}` });
  });
});
// The session may stop on the runner (idle, exited): look again now and then while it's shown.
setInterval(() => { if (state.view === "try" && !document.hidden && !tryState.starting) loadTry().catch(() => {}); }, 20000);

async function loadProcs() {
  if (!state.project) return;
  state.procs = await api("GET", `/api/projects/${state.project.id}/processes`);
  renderProcs();
}

function renderProcs() {
  renderQuick();
  const running = state.procs.filter((p) => p.running).length;
  $("#proc-badge").hidden = !running;
  $("#proc-badge").textContent = running;
  ensureShell();
}

// ------------------------------------------------------------------ history
// The default branch's commit graph, as `git log --graph` draws it.
async function loadGraph() {
  const p = state.project;
  if (!p) return renderGraph(null);
  const res = await api("GET", `/api/projects/${p.id}/graph`);
  if (state.project === p) renderGraph(res);
}

let graphTimer = 0;
const refreshGraph = () => { clearTimeout(graphTimer); graphTimer = setTimeout(() => state.view === "history" && loadGraph().catch(() => {}), 800); };

function renderGraph(res) {
  const lines = res?.graph ? res.graph.split("\n") : [];
  $("#graph-empty").hidden = lines.length > 0;
  $("#graph-empty-text").textContent = state.project ? `${baseBranch(state.project) || "main"} has no commits yet.` : "Select a project to see its main branch.";
  // Commits above origin's tip haven't been pushed yet; dim them so the last push stands out.
  const remote = `origin/${res?.branch || baseBranch(state.project) || "main"}`;
  const isRemote = (line) => line.split("\x1f")[2]?.split(", ").includes(remote);
  let unpushed = lines.some(isRemote);
  $("#graph").replaceChildren(...lines.map((line) => {
    const i = line.indexOf("\x1f");
    const cls = unpushed ? " graph-unpushed" : "";
    if (i < 0) return h("li", { class: "graph-edge" + cls }, h("span", { class: "graph-lines" }, line));
    const [sha, refs, subject, author, when, full] = line.slice(i + 1).split("\x1f");
    const pushed = unpushed && isRemote(line);
    if (pushed) unpushed = false;
    const commit = { sha: full || sha, short: sha, subject, pushed: !cls || pushed };
    const open = (e) => { if (e.type === "click" || e.key === "Enter" || e.key === " ") { e.preventDefault(); commitMenu(commit).catch(fail); } };
    const ref = (r) => r === remote
      ? h("span", { class: "graph-ref remote", title: "Last pushed commit" }, `pushed · ${r}`)
      : h("span", { class: `graph-ref${r.startsWith("tag: ") ? " tag" : ""}` }, r.replace(/^HEAD -> /, ""));
    return h("li", { class: pushed ? "graph-pushed" : cls.trim(), title: cls ? "Not pushed yet" : null },
      h("span", { class: "graph-lines" }, line.slice(0, i)),
      h("span", { class: "graph-commit", role: "button", tabindex: "0", "aria-haspopup": "dialog", "aria-label": `Commit ${sha}: ${subject}`, onclick: open, onkeydown: open },
        h("code", { class: "graph-sha" }, sha),
        ...(refs ? refs.split(", ").map(ref) : []),
        h("span", { class: "graph-subject" }, subject),
        h("span", { class: "graph-meta" }, `${author} · ${when}`)));
  }));
}

// GitHub's web address of a remote ("" if it isn't on GitHub).
function githubURL(remote) {
  const m = /github\.com[:/]([^/]+)\/([^/]+?)(?:\.git)?\/?$/.exec(remote || "");
  return m ? `https://github.com/${m[1]}/${m[2]}` : "";
}

// A commit row's menu in the History view.
async function commitMenu(c) {
  const p = state.project;
  if (!p) return;
  const gh = githubURL(p.remote_url);
  const why = !p.remote_url ? "Connect a remote first" : !c.pushed ? "Push first" : "";
  await menu([
    ["tag", "Tag release…", () => openRelease(c), { disabled: !!why, note: why }],
    ["copy", "Copy SHA", () => copy(c.sha, "SHA copied")],
    ...(gh ? [["external", "Open on GitHub", () => window.open(`${gh}/commit/${c.sha}`, "_blank", "noopener")]] : []),
  ], `${c.short} · ${c.subject}`);
}

// ------------------------------------------------------------------ releases
// "Tag release…" on a pushed commit: pick the next version in the project's
// tag format, edit the notes, and Dash tags the commit and pushes the tag;
// the builds sheet then follows the release workflow.
function tagFormat(fmt) {
  fmt = fmt || "X.Y.Z";
  const [x, y, z] = ["X", "Y", "Z"].map((c) => fmt.indexOf(c));
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const n = "(0|[1-9]\\d*)";
  const parts = [fmt.slice(0, x), fmt.slice(x + 1, y), fmt.slice(y + 1, z), fmt.slice(z + 1)];
  const re = new RegExp(`^${esc(parts[0])}${n}${esc(parts[1])}${n}${esc(parts[2])}${n}${esc(parts[3])}$`);
  return {
    render: (v) => parts[0] + v[0] + parts[1] + v[1] + parts[2] + v[2] + parts[3],
    parse: (t) => { const m = re.exec(t); return m ? [+m[1], +m[2], +m[3]] : null; },
  };
}

let release = null; // { commit, info, format, seq } while the sheet is open
let releaseSeq = 0;

async function openRelease(c) {
  const p = state.project;
  const seq = ++releaseSeq;
  release = { commit: c, info: null, seq, project: p };
  const f = $("#release-form");
  const gh = githubURL(p.remote_url);
  $("#release-commit").replaceChildren(
    gh ? h("a", { href: `${gh}/commit/${c.sha}`, target: "_blank", rel: "noopener" }, h("code", {}, c.short)) : h("code", {}, c.short),
    ` ${c.subject}`);
  $("#release-loading").hidden = false;
  $("#release-loading").textContent = "Fetching tags from origin…";
  $("#release-body").hidden = true;
  $("#release-ok").disabled = true;
  f.custom.value = "";
  $("#release-sheet").returnValue = "";
  $("#release-sheet").showModal();
  let info;
  try {
    info = await api("GET", `/api/projects/${p.id}/release?sha=${encodeURIComponent(c.sha)}`);
  } catch (e) {
    if (release?.seq === seq) $("#release-loading").replaceChildren(h("span", { class: "err-text" }, e.message));
    return;
  }
  if (release?.seq !== seq) return;
  release.info = info;
  release.format = tagFormat(info.format);
  renderRelease();
}

function renderRelease() {
  const { info } = release;
  const f = $("#release-form");
  const s = info.suggestions;
  $("#release-loading").hidden = true;
  $("#release-body").hidden = false;
  $("#release-latest").textContent = info.previous ? `latest: ${info.previous}` : `no ${info.format} tag yet`;
  const choice = (label, tag, note) => h("label", { class: "radio" },
    h("input", { type: "radio", name: "version", value: tag }),
    h("span", {}, label, " ", h("code", {}, tag), h("em", {}, note)));
  $("#release-choices").replaceChildren(...(s.first
    ? [choice("First release", s.first, "no release tag in this format yet")]
    : [choice("Patch", s.patch, "fixes only"), choice("Minor", s.minor, "new features, nothing breaks"), choice("Major", s.major, "breaking changes")]));
  f.querySelector('input[name="version"]').checked = true;
  f.notes.value = info.notes || "";
  f.notes.placeholder = `Release ${s.first || s.patch}`;

  const warn = (text, extra) => h("li", { class: "hint warn" }, text, extra || "");
  const ci = {
    failing: "The build failed on this commit.",
    running: "Builds are still running on this commit.",
    none: "No builds ran on this commit.",
    unknown: githubURL(state.project.remote_url) ? "Couldn't tell whether this commit's build passed." : "",
  }[info.ci.state];
  const failed = info.ci.runs.filter((r) => runState(r)[0] === "failing");
  const items = [
    !info.can_tag && info.cant_tag ? h("li", { class: "hint err-text" }, info.cant_tag) : null,
    ci ? warn(ci, failed.length ? [" ", ...failed.slice(0, 3).map((r) => h("a", { href: r.url, target: "_blank", rel: "noopener" }, r.workflow))] : "") : null,
    info.running ? warn(`${info.running} ${info.running === 1 ? "task is" : "tasks are"} still running or merging; ${info.running === 1 ? "its" : "their"} work won't be in this release.`) : null,
    info.fetch_error ? warn(`Couldn't fetch tags from origin (${info.fetch_error}); the suggestions may be out of date.`) : null,
    info.hint ? warn(info.hint.message, info.hint.suggest ? ` Set the tag format to ${info.hint.suggest} in the project settings.` : "") : null,
  ].filter(Boolean);
  $("#release-warnings").replaceChildren(...items);
  $("#release-warnings").hidden = !items.length;
  syncRelease();
}

// releaseTag is the tag the form would create, or { error }.
function releaseTag() {
  const f = $("#release-form");
  const picked = f.querySelector('input[name="version"]:checked')?.value;
  if (picked !== "custom") return { tag: picked };
  const raw = f.custom.value.trim();
  if (!raw) return { error: "Type a version, like 1.4.0." };
  const fmt = release.format;
  let v = fmt.parse(raw);
  let tag = raw;
  if (!v) {
    const m = /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/.exec(raw);
    if (!m) return { error: `Use a version like 1.4.0 or a tag like ${fmt.render([1, 4, 0])} (format ${release.info.format}).` };
    v = [+m[1], +m[2], +m[3]];
    tag = fmt.render(v);
  }
  if (release.info.tags.includes(tag)) return { error: `${tag} already exists.` };
  const latest = release.info.previous && fmt.parse(release.info.previous);
  const lower = latest && (v[0] - latest[0] || v[1] - latest[1] || v[2] - latest[2]) < 0;
  return { tag, note: `Tags ${tag}${lower ? ` — lower than the latest release, ${release.info.previous}` : ""}.` };
}

function syncRelease() {
  if (!release?.info) return;
  const r = releaseTag();
  const custom = $("#release-form").querySelector('input[name="version"][value="custom"]').checked;
  const hint = $("#release-custom-hint");
  hint.hidden = !custom;
  hint.className = `hint${r.error ? " err-text" : ""}`;
  hint.textContent = r.error || r.note || "";
  $("#release-ok").disabled = !release.info.can_tag || !!r.error;
  setLabel($("#release-ok"), "tag", r.tag ? `Tag ${r.tag} and push` : "Tag and push");
}

$("#release-form").addEventListener("input", syncRelease);
$("#release-form").addEventListener("change", syncRelease);
$("#release-form").custom.addEventListener("focus", (e) => {
  e.target.form.querySelector('input[name="version"][value="custom"]').checked = true;
  syncRelease();
});
$("#release-form").addEventListener("submit", attempt(async (e) => {
  if (e.submitter?.value !== "ok") return;
  e.preventDefault(); // stays open until the tag is pushed (or it fails)
  const r = releaseTag();
  if (r.error || !release?.info) return;
  const { commit, project: p } = release;
  const ok = $("#release-ok");
  ok.disabled = true;
  setLabel(ok, "tag", `Pushing ${r.tag}…`);
  try {
    const out = await api("POST", `/api/projects/${p.id}/tags`, { sha: commit.sha, version: r.tag, notes: $("#release-form").notes.value.trim() });
    release = null;
    $("#release-sheet").close();
    toast(out.build ? "The release workflow is starting; Builds shows how it goes." : `Pushed to origin.`, {
      tone: "ok", icon: "tag", head: `Tagged ${out.tag}`,
      action: out.build ? { label: "Builds", run: openCI } : out.url ? { label: "View", run: () => window.open(out.url, "_blank", "noopener") } : null,
    });
    refreshGraph();
  } finally {
    syncRelease();
  }
}));
$("#release-sheet").addEventListener("close", () => { release = null; });

// ------------------------------------------------------------------ files
// The default branch's files as a tree, and a code editor. Saving
// doesn't write to the branch: it queues a task that commits the edit in its
// own worktree and goes to review. Files git doesn't track (untracked or
// ignored, like .env) are listed too and saved straight to the checkout.
// Each project keeps its open file, so switching projects loses nothing.
const fileSessions = new Map(); // project key → { list, local, tree, open, path, isLocal, blob, original, text, note, size, saved }
const fileText = $("#file-text");
const fileEditor = codeEditor(fileText);
let fileShown = {}; // the session and path the editor holds; another one starts a fresh undo history
function fileSession() {
  if (!state.project) return null;
  const k = projectKey(state.project);
  if (!fileSessions.has(k)) fileSessions.set(k, { list: null, tree: null, open: new Set(), path: null });
  return fileSessions.get(k);
}
const fileDirty = (s) => !!s?.path && !s.note && s.text !== s.original;

async function loadFiles() {
  const s = fileSession(), p = state.project;
  renderFileTree();
  renderFile();
  if (!s) return;
  const res = await api("GET", `/api/projects/${p.id}/files`);
  s.local = new Set(res.local || []);
  s.list = [...res.files, ...s.local].sort();
  s.tree = null;
  if (fileSession() === s) renderFileTree();
}

function fileTreeOf(s) {
  if (s.tree) return s.tree;
  const node = () => ({ dirs: new Map(), files: [] });
  s.tree = node();
  for (const f of s.list) {
    const parts = f.split("/");
    let n = s.tree;
    for (const d of parts.slice(0, -1)) {
      if (!n.dirs.has(d)) n.dirs.set(d, node());
      n = n.dirs.get(d);
    }
    n.files.push(parts.at(-1));
  }
  return s.tree;
}

const fileItem = (s, path, label) => h("button", {
  type: "button", class: `file-item${s.local?.has(path) ? " local" : ""}`,
  title: s.local?.has(path) ? `${path}\nNot in git: saving writes it straight to disk` : path, "aria-current": s.path === path ? "true" : null,
  onclick: () => openFile(path).catch(fail),
}, label);

// Folders render their contents when first opened, so big repositories stay quick.
function dirNodes(s, node, prefix) {
  const dirs = [...node.dirs.keys()].sort().map((name) => {
    const path = prefix + name, sub = node.dirs.get(name);
    const d = h("details", { class: "file-dir", open: s.open.has(path) }, h("summary", { title: path }, name));
    const fill = () => { if (d.childElementCount === 1) d.append(h("div", { class: "file-kids" }, ...dirNodes(s, sub, path + "/"))); };
    if (d.open) fill();
    d.addEventListener("toggle", () => { if (d.open) { s.open.add(path); fill(); } else s.open.delete(path); });
    return d;
  });
  return [...dirs, ...[...node.files].sort().map((name) => fileItem(s, prefix + name, name))];
}

function renderFileTree() {
  const s = fileSession(), tree = $("#file-tree");
  const note = (text) => h("p", { class: "file-note" }, text);
  if (!s) return tree.replaceChildren(note("Select a project to browse its files."));
  if (!s.list) return tree.replaceChildren(note("Loading…"));
  if (!s.list.length) return tree.replaceChildren(note("No files on the default branch yet."));
  const q = $("#file-filter").value.trim().toLowerCase();
  if (!q) return tree.replaceChildren(...dirNodes(s, fileTreeOf(s), ""));
  const hits = s.list.filter((f) => f.toLowerCase().includes(q)), max = 300;
  tree.replaceChildren(...hits.slice(0, max).map((f) => fileItem(s, f, f)),
    hits.length > max ? note(`${hits.length - max} more; type more to narrow it down`) : null,
    hits.length ? null : note("No matching files"));
}

function renderFile() {
  const s = fileSession(), editable = !!s?.path && !s.note, dirty = fileDirty(s);
  $("#file-head").hidden = !s?.path;
  fileEditor.el.hidden = !editable;
  $("#file-empty").hidden = editable;
  if (s?.path) $("#file-path").textContent = s.path;
  if (editable && (fileShown.s !== s || fileShown.path !== s.path || fileText.value !== s.text)) {
    fileEditor.load(s.text, s.path);
    fileShown = { s, path: s.path };
  }
  $("#file-save").disabled = $("#file-revert").disabled = !dirty;
  $("#file-state").textContent = s?.isNew && !s.saved ? "New file, not on the branch yet" : dirty ? "Modified" : editable && s.saved ? (s.isLocal ? "Saved" : "Saved as a task") : s?.isLocal ? "Local file, not in git" : "";
  const save = $("#file-save");
  save.lastChild.textContent = s?.isLocal ? "Save" : "Save as task";
  save.title = s?.isLocal ? "Save to disk (Ctrl+S)" : "Save as a task (Ctrl+S)";
  $("#file-empty-title").textContent = s?.note === "binary" ? "Binary file" : s?.note === "large" ? "File too large" : "No file open";
  $("#file-empty-text").textContent = s?.note === "binary" ? `${s.path} isn't text, so it can't be edited here.`
    : s?.note === "large" ? `${s.path} is ${Math.round(s.size / 1024)} KiB; the editor opens files up to 512 KiB.`
    : s ? "Pick a file on the left to view and edit it. Saving creates a task that goes to review like any other; local files git doesn't track, like .env, are saved straight to disk."
    : "Select a project to browse its files.";
}

async function openFile(path) {
  const s = fileSession(), p = state.project;
  if (!s || s.path === path) return;
  if (fileDirty(s) && !(await ask({ title: `Discard your changes to ${s.path}?`, ok: "Discard", danger: true }))) return;
  const isLocal = !!s.local?.has(path);
  const res = await api("GET", `/api/projects/${p.id}/file?path=${encodeURIComponent(path)}${isLocal ? "&local=1" : ""}`, null, p.prefix || "");
  const text = res.content ?? "";
  Object.assign(s, { path, isLocal, isNew: false, blob: res.blob, original: text, text, size: res.size, saved: false,
    note: res.binary ? "binary" : res.too_large ? "large" : "" });
  if (fileSession() !== s) return;
  renderFile();
  renderFileTree();
}

// newFile opens a file that isn't on the branch yet, starting from
// template; saving it opens a task that creates it.
async function newFile(path, template) {
  const s = fileSession();
  if (!s) return;
  if (s.list?.includes(path)) return openFile(path);
  if (fileDirty(s) && !(await ask({ title: `Discard your changes to ${s.path}?`, ok: "Discard", danger: true }))) return;
  Object.assign(s, { path, isLocal: false, isNew: true, blob: "", original: "", text: template, size: 0, saved: false, note: "" });
  renderFile();
  renderFileTree();
}

async function saveFile() {
  const s = fileSession(), p = state.project;
  if (!fileDirty(s)) return;
  const { path, blob, text } = s;
  if (s.isLocal) {
    const res = await api("PUT", `/api/projects/${p.id}/file`, { path, blob, content: text }, p.prefix || "");
    if (s.path === path) { s.original = text; s.blob = res.blob; s.saved = true; }
    if (fileSession() === s) renderFile();
    toast(`Saved ${path}`);
    return;
  }
  const title = await ask({
    title: "Save as a task", input: true, placeholder: `${s.isNew ? "Create" : "Edit"} ${path}`, ok: "Save as task",
    body: s.isNew ? `${path} is created and committed in its own worktree and goes to review like any other task. Name it, or leave it blank.`
      : `The edit to ${path} is committed in its own worktree and goes to review like any other task. Name it, or leave it blank.`,
  });
  if (title == null) return;
  const t = await api("POST", `/api/projects/${p.id}/edits`, { path, blob, content: text, title }, p.prefix || "");
  if (s.path === path) { s.original = text; s.saved = true; }
  if (fileSession() === s) renderFile();
  toast(`Saved as task “${t.title}”`);
}

fileText.addEventListener("input", () => {
  const s = fileSession();
  if (!s) return;
  const was = fileDirty(s);
  s.text = fileText.value;
  if (was !== fileDirty(s)) renderFile();
});
// Before CodeMirror and vim see it. Tab indents; Escape first to move focus on with Tab.
fileEditor.el.addEventListener("keydown", (e) => {
  if ((e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && e.key.toLowerCase() === "s") { e.preventDefault(); e.stopPropagation(); saveFile().catch(fail); }
}, true);
$("#file-save").addEventListener("click", () => saveFile().catch(fail));
$("#file-revert").addEventListener("click", () => {
  const s = fileSession();
  if (!s) return;
  fileEditor.replace(s.original); // undoable; its input event updates s.text
});
$("#file-filter").addEventListener("input", renderFileTree);
addEventListener("beforeunload", (e) => { if ([...fileSessions.values()].some(fileDirty)) e.preventDefault(); });

// ------------------------------------------------------------------ drag & drop
// Drag a card to another lane to act on it, or within a lane to reorder.
// Mouse: drag after a few pixels. Touch: long-press, then drag (a quick
// swipe still scrolls). Lane tabs are drop targets on phones.
const drag = { active: false, pending: null, t: null, card: null, ghost: null, slot: null, target: null, dx: 0, dy: 0, suppressClick: false };

// What dropping a todo of a status into a lane does (null = not allowed).
function dropAction(t, lane) {
  const from = t.status;
  const to = LANES.find((l) => l.key === lane);
  if (!to) return null;
  if (to.statuses.includes(from)) return ["draft", "queued", "review"].includes(lane) && from !== "failed" ? { kind: "reorder" } : null;
  if (t.reviewing) return null; // locked until the review finishes
  const go = (verb, label) => ({ kind: "action", verb, label });
  if (lane === "queued" && ["draft", "failed"].includes(from)) return go("enqueue", "Added to queue");
  if (lane === "queued" && from === "review") return { kind: "rework" };
  if (lane === "draft" && ["queued", "review", "failed"].includes(from)) return go("cancel", "Moved to drafts");
  if (lane === "merging" && from === "review") return go("approve", "Approved — merging");
  return null;
}

$("#board").addEventListener("pointerdown", (e) => pendDrag(e.target.closest(".todo[data-id]"), e));

// A press on a card (or on its widened hover copy, which passes the board's
// card) may become a drag once the pointer moves.
function pendDrag(card, e) {
  if (!card || e.button > 0) return;
  const t = state.todos.get(card.dataset.id);
  if (!t) return;
  drag.pending = { card, t, x: e.clientX, y: e.clientY, touch: e.pointerType !== "mouse" };
  if (drag.pending.touch) {
    drag.pending.timer = setTimeout(() => drag.pending && startDrag(drag.pending.x, drag.pending.y), 320);
  }
}

document.addEventListener("pointermove", (e) => {
  if (drag.active) { moveDrag(e.clientX, e.clientY); return; }
  const p = drag.pending;
  if (!p) return;
  const dist = Math.hypot(e.clientX - p.x, e.clientY - p.y);
  if (p.touch) { if (dist > 10) cancelPending(); return; } // it's a scroll
  if (dist > 6) startDrag(e.clientX, e.clientY);
});
// While dragging on touch, stop the page from scrolling under the finger.
document.addEventListener("touchmove", (e) => { if (drag.active) e.preventDefault(); }, { passive: false });
document.addEventListener("pointerup", (e) => { if (drag.active) endDrag(e.clientX, e.clientY); cancelPending(); });
document.addEventListener("pointercancel", () => { if (drag.active) abortDrag(); cancelPending(); });
document.addEventListener("keydown", (e) => { if (drag.active && e.key === "Escape") { e.stopPropagation(); abortDrag(); } }, true);
// A drag ends with a click on the card; swallow it so the detail doesn't open.
document.addEventListener("click", (e) => { if (drag.suppressClick) { e.stopPropagation(); e.preventDefault(); drag.suppressClick = false; } }, true);
$("#board").addEventListener("contextmenu", (e) => { if (e.target.closest(".todo")) e.preventDefault(); });

function cancelPending() {
  if (drag.pending?.timer) clearTimeout(drag.pending.timer);
  drag.pending = null;
}

function startDrag(x, y) {
  const { card, t } = drag.pending;
  cancelPending();
  hoverCard.close();
  const r = card.getBoundingClientRect();
  drag.active = true;
  drag.t = t;
  drag.card = card;
  // Clamped: a drag from the widened hover copy can start outside the card.
  drag.dx = Math.max(0, Math.min(x - r.left, r.width - 16));
  drag.dy = Math.max(0, Math.min(y - r.top, r.height - 8));
  drag.ghost = card.cloneNode(true);
  drag.ghost.classList.add("drag-ghost");
  drag.ghost.style.width = `${r.width}px`;
  document.body.append(drag.ghost);
  drag.slot = h("li", { class: "drop-slot", "aria-hidden": "true" });
  drag.slot.style.height = `${r.height}px`;
  card.classList.add("dragging");
  document.body.classList.add("is-dragging");
  navigator.vibrate?.(12);
  markTargets();
  showDropBar();
  moveDrag(x, y);
}

// On phones the other lanes are off-screen, so a drag shows a bar of large
// drop targets for exactly the moves this card allows.
const DROP_LABEL = { enqueue: "Add to queue", cancel: "Back to drafts", approve: "Approve and merge" };
function showDropBar() {
  if (desktop.matches) return;
  const zones = LANES.map((l) => [l, dropAction(drag.t, l.key)])
    .filter(([l, a]) => a && a.kind !== "reorder")
    .map(([l, a]) => h("div", { class: `drop-zone s-${l.key === "done" ? "merged" : l.key}`, "data-lane": l.key },
      a.kind === "rework" ? "Send back for rework" : DROP_LABEL[a.verb] || l.label));
  const bar = h("div", { class: "drop-bar", id: "drop-bar" },
    zones.length ? zones : h("div", { class: "drop-zone none" }, "Drag up or down to reorder"));
  document.body.append(bar);
}

// Highlight lanes (columns and mobile tabs) where this card may be dropped.
function markTargets() {
  for (const el of $$(".col[data-lane], .lane-tab[data-lane]")) {
    const ok = !!dropAction(drag.t, el.dataset.lane);
    el.classList.toggle("drop-ok", ok);
    el.classList.toggle("drop-no", !ok);
  }
}

function moveDrag(x, y) {
  drag.ghost.style.transform = `translate(${x - drag.dx}px, ${y - drag.dy}px) rotate(1.2deg) scale(1.02)`;
  const under = document.elementFromPoint(x, y);
  const laneEl = under?.closest(".drop-zone[data-lane], .col[data-lane], .lane-tab[data-lane]");
  const lane = laneEl?.dataset.lane || null;
  const action = lane ? dropAction(drag.t, lane) : null;
  $$(".drop-over").forEach((el) => el !== laneEl && el.classList.remove("drop-over"));
  drag.target = action ? { lane, action, index: Infinity } : null;
  if (!action) { drag.slot.remove(); return; }
  laneEl.classList.add("drop-over");

  // Inside a visible column, show where the card would land.
  const col = laneEl.classList.contains("col") ? laneEl : null;
  const rail = col?.querySelector(".rail") || null;
  if (!col || laneEl.matches(".col:not(.active)") && !desktop.matches) { drag.slot.remove(); return; }
  const cards = [...col.querySelectorAll(".todo[data-id]")].filter((c) => c !== drag.card);
  let index = cards.findIndex((c) => { const r = c.getBoundingClientRect(); return y < r.top + r.height / 2; });
  if (index < 0) index = cards.length;
  drag.target.index = index;
  if (rail) {
    const ref = cards[index]?.closest("li") || null;
    if (drag.slot.nextSibling !== ref || drag.slot.parentNode !== rail) rail.insertBefore(drag.slot, ref);
  } else {
    col.querySelector(".col-body")?.prepend(drag.slot);
  }
  autoScroll(col.querySelector(".col-body") || document.scrollingElement, y);
}

function autoScroll(el, y) {
  const r = el === document.scrollingElement ? { top: 0, bottom: innerHeight } : el.getBoundingClientRect();
  if (y < r.top + 60) el.scrollBy({ top: -14 });
  else if (y > r.bottom - 60) el.scrollBy({ top: 14 });
}

function cleanupDrag() {
  drag.ghost?.remove();
  drag.slot?.remove();
  const bar = $("#drop-bar");
  if (bar) leave(bar, "leaving", () => bar.remove(), 160);
  drag.card?.classList.remove("dragging");
  document.body.classList.remove("is-dragging");
  $$(".drop-ok, .drop-no, .drop-over").forEach((el) => el.classList.remove("drop-ok", "drop-no", "drop-over"));
  drag.active = false;
  drag.suppressClick = true;
  setTimeout(() => { drag.suppressClick = false; }, 0);
}

function abortDrag() {
  // Fly the ghost back to where the card was.
  const g = drag.ghost, home = drag.card.getBoundingClientRect();
  if (g && !reduceMotion.matches) {
    g.animate([{ transform: g.style.transform }, { transform: `translate(${home.left}px, ${home.top}px)` }], { duration: 200, easing: EASE });
    setTimeout(() => { cleanupDrag(); renderBoard(); }, 190);
  } else { cleanupDrag(); renderBoard(); }
}

async function endDrag() {
  const target = drag.target, t = drag.t;
  if (!target) return abortDrag();
  cleanupDrag();
  try {
    if (target.action.kind === "reorder") {
      await reorder(t, target.lane, target.index);
    } else if (target.action.kind === "rework") {
      renderBoard();
      const feedback = await ask({ title: "Send back for rework", body: "Claude continues in the same worktree with your notes.", input: true, placeholder: "What should change?", ok: "Send back" });
      if (feedback === null) return;
      await api("POST", `/api/todos/${t.id}/rework`, { feedback });
      toast("Sent back for rework");
    } else {
      // Optimistic: show it in the new lane right away; the server event confirms.
      const lane = LANES.find((l) => l.key === target.lane);
      state.todos.set(t.id, { ...t, status: lane.statuses[0] });
      renderBoard();
      await api("POST", `/api/todos/${t.id}/${target.action.verb}`);
      toast(target.action.label);
      if (target.lane === "queued" && Number.isFinite(target.index)) await reorder(state.todos.get(t.id), "queued", target.index);
    }
  } catch (err) {
    state.todos.set(t.id, t); // undo the optimistic move
    renderBoard();
    fail(err);
  }
}

// Reorder a lane by rewriting priorities 0..n-1 (lower runs first).
async function reorder(t, laneKey, index) {
  const lane = laneItems()[laneKey].filter((x) => x.id !== t.id);
  lane.splice(Math.min(index, lane.length), 0, t);
  const changes = lane.map((x, i) => [x, i]).filter(([x, i]) => x.priority !== i);
  for (const [x, i] of changes) state.todos.set(x.id, { ...state.todos.get(x.id), priority: i });
  renderBoard();
  await Promise.all(changes.map(([x, i]) => api("PATCH", `/api/todos/${x.id}`, { priority: i })));
}

// ------------------------------------------------------------------ hover card
// On the desktop board with a mouse, resting on a card shows it widened to a
// readable width, floating over the neighbouring columns. The columns don't
// change: the widened card is a copy, fixed over the card, outside the
// scrolling column so nothing clips it. It is rendered from the task like the
// card, with its own handlers, and follows the card's live updates. A press
// on it starts a drag of the card itself.
const HOVER_DELAY = 300, HOVER_W = 460, HOVER_MARGIN = 12;
const canHover = matchMedia("(hover: hover) and (pointer: fine)");
const hoverCard = {
  el: null, card: null, row: null, rect: null, waiting: null, timer: 0, watch: null,
  want(card) {
    if (card === this.card || card === this.waiting) return;
    this.cancel();
    if (!card || !desktop.matches || !canHover.matches || drag.active || drag.pending) return;
    this.waiting = card;
    this.timer = setTimeout(() => {
      this.waiting = null;
      // Live updates may have re-rendered the board meanwhile: take today's card.
      const now = card.isConnected ? card : $(`#board .todo[data-id="${CSS.escape(card.dataset.id)}"]`);
      if (now) this.open(now);
    }, HOVER_DELAY);
  },
  cancel() { clearTimeout(this.timer); this.waiting = null; },
  open(card) {
    if (drag.active || drag.pending || !card.matches(":hover")) return;
    this.close();
    const r = card.getBoundingClientRect();
    const w = Math.max(r.width, Math.min(HOVER_W, innerWidth - 2 * HOVER_MARGIN));
    const sub = card.querySelector(".todo-sub");
    // Already wide and nothing cut off: there is nothing more to show.
    if (w <= r.width + 1 && !(sub && sub.scrollHeight > sub.clientHeight + 1)) return;
    this.card = card;
    this.el = h("div", { class: "todo-float", "aria-hidden": "true",
      onpointerleave: (e) => { if (e.pointerType !== "touch") this.close(); },
      onpointerdown: (e) => { if (this.card) pendDrag(this.card, e); },
      // The wheel scrolls the column underneath, as it would without the copy.
      onwheel: (e) => { const body = this.card?.closest(".col-body"); this.close(); body?.scrollBy({ top: e.deltaY, left: e.deltaX }); },
      oncontextmenu: (e) => e.preventDefault(),
    });
    document.body.append(this.el);
    this.render();
    this.place(r, w);
    this.watch = new MutationObserver(() => this.render());
    this.observe();
  },
  observe() {
    this.watch.disconnect();
    this.watch.observe(this.card, { attributes: true, attributeFilter: ["class"], childList: true, subtree: true, characterData: true });
  },
  // Copies the card: fresh content from the task, the card's classes (status,
  // selection, keyboard cursor). The row element stays, so a press that
  // started on it still ends in a click.
  render() {
    const t = this.card && state.todos.get(this.card.dataset.id);
    if (!t) return this.close();
    const fresh = todoRow(t);
    if (!this.row) {
      this.row = fresh;
      this.row.removeAttribute("data-id"); // board code looks cards up by data-id; this isn't one
      this.row.tabIndex = -1;
      this.el.append(this.row);
    } else {
      this.row.replaceChildren(...fresh.childNodes);
    }
    this.row.className = this.card.className;
    this.row.style.minHeight = `${this.card.offsetHeight}px`; // always covers the card
  },
  place(r, w) {
    const el = this.el;
    this.rect = r;
    let left = r.left;
    if (left + w > innerWidth - HOVER_MARGIN) left = r.right - w; // rightmost column: grow to the left
    left = Math.max(HOVER_MARGIN, Math.min(left, innerWidth - HOVER_MARGIN - w));
    el.style.width = `${w}px`;
    el.style.maxHeight = `${innerHeight - 2 * HOVER_MARGIN}px`;
    el.style.left = `${left}px`;
    el.style.top = `${r.top}px`;
    const hgt = el.offsetHeight;
    if (r.top + hgt > innerHeight - HOVER_MARGIN) el.style.top = `${Math.max(HOVER_MARGIN, innerHeight - HOVER_MARGIN - hgt)}px`;
  },
  // After the board re-renders: follow the new card, or close if it moved.
  sync() {
    if (!this.card || this.card.isConnected) return; // same card: the observer follows it
    const card = $(`#board .todo[data-id="${CSS.escape(this.card.dataset.id)}"]`);
    // Gone, or gliding to a new place (FLIP): the pointer is no longer on it.
    if (!card || drag.active || card.getAnimations().length) return this.close();
    const r = card.getBoundingClientRect();
    if (Math.abs(r.left - this.rect.left) > 1 || Math.abs(r.top - this.rect.top) > 1 || Math.abs(r.width - this.rect.width) > 1) return this.close();
    this.card = card;
    this.observe();
    this.render();
    this.place(r, parseFloat(this.el.style.width));
  },
  close() {
    this.cancel();
    this.watch?.disconnect();
    this.el?.remove();
    this.el = this.card = this.row = this.watch = null;
  },
};
$("#board").addEventListener("pointerover", (e) => {
  if (e.pointerType === "touch" || e.buttons) return;
  hoverCard.want(e.target.closest(".todo[data-id]"));
});
$("#board").addEventListener("pointerout", (e) => {
  const card = e.target.closest(".todo[data-id]");
  if (card && card === hoverCard.waiting && !card.contains(e.relatedTarget)) hoverCard.cancel();
});
addEventListener("scroll", (e) => { if (hoverCard.el && !hoverCard.el.contains(e.target)) hoverCard.close(); }, true);
addEventListener("resize", () => hoverCard.close());
addEventListener("blur", () => hoverCard.close());
desktop.addEventListener("change", () => hoverCard.close());

// ------------------------------------------------------------------ issues
// A standing list of what is wrong with the project (bugs, vulnerabilities,
// other problems), added by hand, by scans and by running tasks. Checking
// issues and creating tasks for them is the triage step; a merged task
// resolves its issues.
const SEVERITIES = ["critical", "high", "medium", "low", "info"];
const ISSUE_TYPES = { bug: "Bug", vuln: "Vulnerability", issue: "Issue" };
const ISSUE_STATUSES = { open: "Open", task_created: "Task created", resolved: "Resolved", dismissed: "Dismissed" };
const triageable = (i) => i.status === "open" || i.status === "task_created";
// Only open issues are picked for bulk actions: one with a task is already
// being dealt with (it can still get another task or be dismissed from its
// own row).
const pickable = (i) => i.status === "open";
// The list is grouped by where an issue stands, in this order.
const ISSUE_GROUPS = [
  { key: "open", label: "Needs triage", hint: "Not dealt with yet: create a task or dismiss" },
  { key: "task", label: "In a task", hint: "A task is working on these; they are resolved when it is merged" },
  { key: "closed", label: "Closed", hint: "Resolved or dismissed" },
];
const issueGroup = (i) => i.status === "open" ? "open" : i.status === "task_created" ? "task" : "closed";
// The task linked to an issue that says most about where it stands: one
// still going beats one that failed beats a merged one.
function issueTask(i) {
  const ts = (i.todo_ids || []).map((id) => state.todos.get(id)).filter(Boolean);
  const rank = (t) => ({ in_progress: 0, merging: 1, review: 2, queued: 3, draft: 4, failed: 5, merged: 6 })[t.status] ?? 7;
  return ts.sort((a, b) => rank(a) - rank(b))[0] || null;
}
const taskLabel = (t) => !t ? "Task" : t.paused ? "Paused" : STATUS_LABEL[t.status] || t.status;
const iss = {
  list: [],
  loaded: false,      // list holds the project's issues (scan reports read their status from it)
  checked: new Set(), // ids picked for a bulk action
  expanded: new Set(),
  editing: null,      // id of the issue whose fields are being edited
  filter: { type: "", severity: "", status: "active", source: "", run: null }, // run: { id, ids, label } from a scan report
};

function sortIssues() {
  iss.list.sort((a, b) => (SEVERITIES.indexOf(a.severity) - SEVERITIES.indexOf(b.severity)) || (new Date(b.created_at) - new Date(a.created_at)));
}

async function loadIssues() {
  const p = state.project;
  if (!p) return;
  const list = await api("GET", `/api/projects/${p.id}/issues`);
  if (state.project !== p) return;
  iss.list = list;
  iss.loaded = true;
  sortIssues();
  renderIssues();
  if (state.view === "scans") renderScans();
}

function resetIssues() {
  iss.filter.run = null;
  iss.list = [];
  iss.loaded = false;
  iss.checked.clear();
  iss.expanded.clear();
  iss.editing = null;
  renderIssues();
}

function onIssueEvent(ev) {
  const id = ev.data?.id;
  if (!id) return;
  iss.list = iss.list.filter((i) => i.id !== id);
  if (ev.type === "issue.updated") { iss.list.push(ev.data); sortIssues(); }
  else { iss.checked.delete(id); iss.expanded.delete(id); }
  renderIssues();
  if (state.view === "scans") renderScans();
}

function issueVisible(i) {
  const f = iss.filter;
  if (f.run && !f.run.ids.has(i.id)) return false;
  if (f.type && i.type !== f.type) return false;
  if (f.severity && i.severity !== f.severity) return false;
  if (f.status === "active" ? !triageable(i) : f.status && f.status !== "all" && i.status !== f.status) return false;
  if (f.source && i.source !== f.source && !i.source.startsWith(f.source + ":")) return false;
  return true;
}

const issueLoc = (i) => i.file ? (i.line ? `${i.file}:${i.line}` : i.file) : "";
const sourceLabel = (s) => s === "manual" ? "Added by hand" : s.startsWith("scan:") ? `Scan: ${s.slice(5)}` : s === "agent:chat" ? "Reported from the chat" : s.startsWith("agent:") ? "Reported by a task" : s;

function renderIssueBadge() {
  const n = iss.list.filter((i) => i.status === "open").length;
  const b = $("#issue-badge");
  b.hidden = !n;
  b.textContent = n;
  b.title = `${n} open issue${n === 1 ? "" : "s"}`;
}

function renderIssues() {
  renderIssueBadge();
  const list = $("#issue-list");
  const shown = iss.list.filter(issueVisible);
  for (const id of iss.checked) if (!iss.list.some((i) => i.id === id && pickable(i))) iss.checked.delete(id);
  // Grouped by where they stand; headings only when there is more than one group.
  const groups = ISSUE_GROUPS.map((g) => ({ ...g, items: shown.filter((i) => issueGroup(i) === g.key) })).filter((g) => g.items.length);
  list.replaceChildren(...groups.flatMap((g) => [
    groups.length > 1 ? h("li", { class: `issue-group g-${g.key}`, title: g.hint }, h("span", {}, g.label), h("span", { class: "issue-group-n" }, g.items.length)) : null,
    ...g.items.map(issueRow),
  ].filter(Boolean)));
  const empty = $("#issue-empty");
  empty.hidden = shown.length > 0;
  $("#issue-empty-title").textContent = !state.project ? "No project" : iss.list.length ? "No issues match" : "No issues";
  $("#issue-empty-text").textContent = !state.project ? "Select a project to see its issues."
    : iss.list.length ? "Change the filters to see the others."
    : "Bugs, vulnerabilities and other problems go here: add one above, or let scans and running tasks report what they find. Check issues to turn them into tasks.";
  $("#issue-add").hidden = !state.project;
  $("#issue-tools").hidden = !state.project || !iss.list.length;
  const runChip = $("#issue-f-run");
  runChip.hidden = !iss.filter.run;
  runChip.replaceChildren(...(iss.filter.run ? [h("span", {}, iss.filter.run.label), ico("x")] : []));
  // Sources seen so far, for the source filter.
  const sel = $("#issue-f-source");
  const kinds = [...new Set(iss.list.map((i) => i.source.split(":")[0]))];
  const want = ["", ...["manual", "scan", "agent"].filter((k) => kinds.includes(k))];
  if ([...sel.options].map((o) => o.value).join() !== want.join()) {
    sel.replaceChildren(...want.map((k) => h("option", { value: k }, { "": "Any source", manual: "Added by hand", scan: "Scans", agent: "Agents" }[k])));
    if (!want.includes(iss.filter.source)) iss.filter.source = "";
    sel.value = iss.filter.source;
  }
  renderIssueBulk();
}

// renderIssueBulk updates what depends on the checked issues only, so
// ticking a box doesn't rebuild the list (and lose focus).
function renderIssueBulk() {
  const shown = iss.list.filter(issueVisible);
  const picked = shown.filter((i) => iss.checked.has(i.id));
  const all = $("#issue-all");
  const can = shown.filter(pickable);
  all.checked = can.length > 0 && picked.length === can.length;
  all.indeterminate = picked.length > 0 && picked.length < can.length;
  all.disabled = !can.length;
  $("#issue-bulk").hidden = !iss.checked.size;
  $("#issue-count").textContent = `${iss.checked.size} selected`;
  $("#issue-combine").disabled = iss.checked.size < 2;
}

function issueRow(i) {
  const open = iss.expanded.has(i.id);
  const toggle = () => {
    open ? iss.expanded.delete(i.id) : iss.expanded.add(i.id);
    renderIssues();
    $(`#issue-list .issue[data-id="${i.id}"] .issue-main`)?.focus();
  };
  // Each linked task, with where it stands; the busiest first.
  const linked = (i.todo_ids || []).map((id) => ({ id, t: state.todos.get(id) }));
  const lead = issueTask(i);
  linked.sort((a, b) => (b.t === lead) - (a.t === lead));
  const tasks = linked.map(({ id, t }) => issueTaskChip(id, t));
  // An issue with a task shows what the task is doing where the checkbox
  // would be: it is being dealt with, not waiting to be picked.
  const running = lead && !lead.paused && (lead.status === "in_progress" || lead.status === "merging");
  const mark = i.status === "task_created"
    ? h("span", { class: `issue-mark${lead ? ` s-${lead.status}` : ""}`, title: lead ? `A task is on it: ${taskLabel(lead)}` : "A task is on it", role: "img", "aria-label": "In a task" },
      running ? h("span", { class: "act-spin", "aria-hidden": "true" }) : ico(lead?.status === "failed" ? "x" : "draft"))
    : h("input", { type: "checkbox", class: "issue-check", checked: iss.checked.has(i.id), disabled: !pickable(i),
      "aria-label": `Select ${i.title}`, title: pickable(i) ? "Select for a bulk action" : `${ISSUE_STATUSES[i.status]}; reopen it to triage`,
      onchange: (e) => { e.target.checked ? iss.checked.add(i.id) : iss.checked.delete(i.id); renderIssueBulk(); } });
  return h("li", { class: `issue status-${i.status}${lead?.status === "failed" && i.status === "task_created" ? " task-failed" : ""}${open ? " open" : ""}`, "data-id": i.id },
    h("div", { class: "issue-row" },
      mark,
      h("span", { class: `sev sev-${i.severity}`, title: `Severity: ${i.severity}` }, i.severity),
      h("button", { type: "button", class: "issue-main", "aria-expanded": String(open), onclick: toggle },
        h("span", { class: `issue-type type-${i.type}` }, i.type === "vuln" ? "vuln" : i.type),
        h("span", { class: "issue-title" }, i.title),
        issueLoc(i) ? h("span", { class: "issue-loc" }, issueLoc(i)) : null),
      ...tasks,
      i.status === "resolved" || i.status === "dismissed" ? h("span", { class: "issue-status" }, ISSUE_STATUSES[i.status]) : null),
    open ? (iss.editing === i.id ? issueEditor(i) : issueBody(i)) : null);
}

// issueTaskChip is a linked task as a pill that opens it and says where it
// stands (Draft, Queued, Running, Ready for review, Failed, Merged).
function issueTaskChip(id, t) {
  const busy = t && !t.paused && (t.status === "in_progress" || t.status === "merging");
  return h("button", { type: "button", class: `issue-task${t ? ` s-${t.status}` : ""}`, title: t ? `${title(t)}: ${taskLabel(t)}. Open the task` : "Open the task", onclick: () => openDetail(id) },
    busy ? h("span", { class: "act-spin", "aria-hidden": "true" }) : ico(t?.status === "merged" ? "merge" : t?.status === "failed" ? "x" : "draft"),
    taskLabel(t));
}

// issueTaskNote explains, in an issue with a task, what happens next.
function issueTaskNote(i) {
  if (i.status !== "task_created") return null;
  const t = issueTask(i);
  const n = (i.todo_ids || []).length;
  const next = !t ? "It is resolved when its task is merged."
    : t.paused ? "The task is paused; resume it to carry on."
    : { draft: "The task is a draft: start it from the board to have it fixed.",
        queued: "The task is queued and starts when a slot is free.",
        in_progress: "The task is running now.",
        merging: "The task is being merged; the issue is resolved when it lands.",
        review: "The task is done and waiting for your review; merging it resolves this issue.",
        failed: "The task failed: open it to retry, or create another task.",
      }[t.status] || "It is resolved when the task is merged.";
  return h("div", { class: `issue-tasknote${t ? ` s-${t.status}` : ""}` },
    h("p", {}, h("strong", {}, n > 1 ? `${n} tasks are on this issue. ` : "A task is on this issue. "), next),
    t ? ib({ type: "button", class: "btn small", onclick: () => openDetail(t.id) }, "right", "Open the task") : null);
}

function issueBody(i) {
  const act = (label, icon, run, cls = "btn small") => ib({ type: "button", class: cls, onclick: attempt(run) }, icon, label);
  const patch = (body) => api("PATCH", `/api/issues/${i.id}`, body);
  return h("div", { class: "issue-body" },
    h("p", { class: "issue-meta" },
      `${ISSUE_TYPES[i.type] || i.type} · ${sourceLabel(i.source)} · ${ago(i.created_at)} ago`,
      i.updated_at !== i.created_at ? ` · updated ${ago(i.updated_at)} ago` : "",
      i.rule ? ` · rule ${i.rule}` : ""),
    issueTaskNote(i),
    i.status === "dismissed" ? h("p", { class: "issue-reason" }, `Dismissed${i.dismiss_reason ? `: ${i.dismiss_reason}` : ""}`) : null,
    i.details ? h("div", { class: "issue-md", innerHTML: renderMarkdown(i.details) }) : h("p", { class: "issue-none" }, "No details yet."),
    i.fix ? h("div", { class: "issue-fix" }, h("h4", {}, "Suggested fix"), h("div", { class: "issue-md", innerHTML: renderMarkdown(i.fix) })) : null,
    h("div", { class: "issue-actions" },
      act("Edit", "edit", () => { iss.editing = i.id; renderIssues(); }),
      triageable(i) ? act(i.status === "task_created" ? "Create another task" : "Create task", "plus", () => issueTasks([i.id], false, false)) : null,
      triageable(i) ? act("Dismiss", "x", () => dismissIssues([i.id])) : null,
      i.status === "open" ? act("Mark resolved", "check", () => patch({ status: "resolved" })) : null,
      !triageable(i) ? act("Reopen", "undo", () => patch({ status: "open" })) : null,
      act("Delete", "trash", async () => {
        if (await ask({ title: "Delete this issue?", body: `“${i.title}” is forgotten. If it is reported again it comes back as new; dismiss it instead to keep it out.`, ok: "Delete", danger: true }))
          await api("DELETE", `/api/issues/${i.id}`);
      }, "btn small danger")));
}

function issueEditor(i) {
  const f = (name, el) => h("label", { class: `issue-field f-${name}` }, h("span", {}, name[0].toUpperCase() + name.slice(1)), el);
  const titleIn = h("input", { value: i.title, required: true, autocomplete: "off" });
  const typeIn = h("select", {}, ...Object.entries(ISSUE_TYPES).map(([v, l]) => h("option", { value: v, selected: v === i.type }, l)));
  const sevIn = h("select", {}, ...SEVERITIES.map((v) => h("option", { value: v, selected: v === i.severity }, v[0].toUpperCase() + v.slice(1))));
  const fileIn = h("input", { value: i.file || "", placeholder: "path/to/file", autocomplete: "off", spellcheck: false });
  const lineIn = h("input", { type: "number", min: 0, value: i.line || "", placeholder: "Line" });
  const detailsIn = h("textarea", { rows: 5, placeholder: "What happens, why it is wrong, how to reproduce (markdown)" });
  detailsIn.value = i.details || "";
  const fixIn = h("textarea", { rows: 3, placeholder: "How it could be fixed (markdown)" });
  fixIn.value = i.fix || "";
  const cancel = () => { iss.editing = null; renderIssues(); };
  const form = h("form", { class: "issue-body issue-edit", onsubmit: attempt(async (e) => {
    e.preventDefault();
    await api("PATCH", `/api/issues/${i.id}`, {
      title: titleIn.value, type: typeIn.value, severity: sevIn.value, file: fileIn.value,
      line: parseInt(lineIn.value, 10) || 0, details: detailsIn.value, fix: fixIn.value,
    });
    iss.editing = null;
    renderIssues();
  }), onkeydown: (e) => { if (e.key === "Escape") { e.stopPropagation(); cancel(); } } },
    f("title", titleIn),
    h("div", { class: "issue-edit-row" }, f("type", typeIn), f("severity", sevIn), f("file", fileIn), f("line", lineIn)),
    f("details", detailsIn),
    f("fix", fixIn),
    h("div", { class: "issue-actions" },
      ib({ type: "submit", class: "btn small primary" }, "check", "Save"),
      h("button", { type: "button", class: "btn small", onclick: cancel }, "Cancel")));
  requestAnimationFrame(() => titleIn.focus());
  return form;
}

async function issueTasks(ids, combine, enqueue) {
  const todos = await api("POST", `/api/projects/${state.project.id}/issues/tasks`, { ids, combine, enqueue });
  for (const id of ids) iss.checked.delete(id);
  for (const t of todos) state.todos.set(t.id, t);
  renderIssues();
  const n = todos.length;
  const what = `${n} ${enqueue ? "queued" : "draft"} task${n === 1 ? "" : "s"}`;
  toast(n === 1 ? title(todos[0]) : `For ${ids.length} issues`, { tone: "ok", head: `Created ${what}`, action: n === 1 ? openTodo(todos[0].id) : { label: "Board", run: () => showView("board") } });
}

async function dismissIssues(ids) {
  const reason = await ask({
    title: ids.length === 1 ? "Dismiss this issue?" : `Dismiss ${ids.length} issues?`,
    body: "Dismissed issues stay dismissed when they are reported again. You can reopen them later.",
    input: true, placeholder: "Why? e.g. false positive, won't fix, by design", ok: "Dismiss",
  });
  if (reason === null) return;
  await api("POST", `/api/projects/${state.project.id}/issues/dismiss`, { ids, reason });
  for (const id of ids) iss.checked.delete(id);
  renderIssues();
}

$("#issue-add").addEventListener("submit", attempt(async (e) => {
  e.preventDefault();
  const input = $("#issue-add-title");
  const t = input.value.trim();
  if (!t || !state.project) return;
  const { issue, result } = await api("POST", `/api/projects/${state.project.id}/issues`, { title: t, type: $("#issue-add-type").value });
  input.value = "";
  if (result === "known" || result === "updated") toast(issue.title, { head: "Already on the list" });
  if (result === "reopened") toast(issue.title, { head: "Reopened: it had been resolved" });
  if (result === "dismissed") toast(issue.title, { head: "Already dismissed", action: { label: "Show", run: () => { iss.filter.status = "dismissed"; $("#issue-f-status").value = "dismissed"; iss.expanded.add(issue.id); renderIssues(); } } });
  if (result === "new") {
    // The live event may have added it already; show it either way, opened.
    if (!iss.list.some((i) => i.id === issue.id)) { iss.list.push(issue); sortIssues(); }
    iss.expanded.add(issue.id);
    renderIssues();
  }
}));
for (const [key, id] of [["type", "#issue-f-type"], ["severity", "#issue-f-severity"], ["status", "#issue-f-status"], ["source", "#issue-f-source"]]) {
  $(id).addEventListener("change", (e) => { iss.filter[key] = e.target.value; renderIssues(); });
}
$("#issue-all").addEventListener("change", (e) => {
  for (const i of iss.list.filter(issueVisible).filter(pickable)) e.target.checked ? iss.checked.add(i.id) : iss.checked.delete(i.id);
  for (const box of $$("#issue-list .issue-check")) if (!box.disabled) box.checked = e.target.checked;
  renderIssueBulk();
});
$("#issue-tasks").addEventListener("click", attempt(() => issueTasks([...iss.checked], false, $("#issue-queue").checked)));
$("#issue-combine").addEventListener("click", attempt(() => issueTasks([...iss.checked], true, $("#issue-queue").checked)));
$("#issue-dismiss").addEventListener("click", attempt(() => dismissIssues([...iss.checked])));
$("#issue-clear").addEventListener("click", () => { iss.checked.clear(); renderIssues(); });

// ------------------------------------------------------------------ scans
// Preconfigured, read-only reviews of the project (security, code review,
// dependency audit, or the team's own templates in .dash/scans/) that run on
// demand or on a schedule and file what they find in Issues.
const SCAN_KINDS = { security: "Security", code_review: "Code review", dependencies: "Dependencies", custom: "Custom" };
const SCAN_SCOPES = { repo: "Whole repository", since_last_scan: "Changes since the last scan", since_main: "Branch vs. main", path: "One path" };
const scans = { list: [], problems: [], builtin: false, dir: ".dash/scans", loaded: false, history: new Map() };
const plural = (n, one, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;

async function loadScans() {
  const p = state.project;
  if (!p) return;
  const r = await api("GET", `/api/projects/${p.id}/scans`);
  if (state.project !== p) return;
  Object.assign(scans, { list: r.scans, problems: r.problems, builtin: r.builtin, dir: r.dir, loaded: true });
  for (const name of scans.history.keys()) loadScanHistory(name).catch(() => {});
  renderScans();
}

function resetScans() {
  Object.assign(scans, { list: [], problems: [], builtin: false, loaded: false });
  scans.history.clear();
  renderScans();
}

async function loadScanHistory(name) {
  const p = state.project;
  const runs = await api("GET", `/api/projects/${p.id}/scan-runs?scan=${encodeURIComponent(name)}`);
  if (state.project !== p) return;
  scans.history.set(name, runs);
  renderScans();
}

function onScanRun(ev) {
  const run = ev.data;
  const s = scans.list.find((x) => x.name === run.scan);
  if (s) {
    if (!s.last_run || s.last_run.id === run.id || new Date(run.started_at) >= new Date(s.last_run.started_at)) {
      if (s.last_run?.status === "succeeded" && s.last_run.id !== run.id) s.last_report = s.last_run;
      s.last_run = run;
      if (run.status === "succeeded") s.last_report = null;
    }
    if (run.status === "running") s.running = run.id;
    else if (s.running === run.id) s.running = "";
  }
  const hist = scans.history.get(run.scan);
  if (hist) {
    const i = hist.findIndex((x) => x.id === run.id);
    if (i >= 0) hist[i] = run; else hist.unshift(run);
  }
  if (run.status !== "running" && s && !s.running) loadScans().catch(() => {}); // the next run time moved
  renderScans();
  scanFinished(run, state.project);
}

// scanFinished tells about a run that just ended: always for one started by
// hand, and for a scheduled or resumed one when it found new critical or
// high issues.
function scanFinished(run, p, where = "") {
  if (run.status === "running" || !run.finished_at) return;
  const go = p ? { label: "Show", run: async () => { if (state.project !== p) await selectProject(p); showRunIssues(run, "new"); } } : null;
  const head = `${scanLabel(run.scan)}${where ? ` · ${where}` : ""}`;
  if (run.trigger !== "manual") {
    if (run.status !== "succeeded" || !run.urgent) return;
    const msg = `${plural(run.urgent, "new critical or high issue")} · ${scanSummary(run)}`;
    toast(msg, { tone: "error", icon: "bug", head, action: go, ms: 12000 });
    if (notifyOn() && "Notification" in window && Notification.permission === "granted" && !(document.visibilityState === "visible" && document.hasFocus())) {
      const n = new Notification(head, { body: msg, tag: `dash-scan-${run.id}` });
      n.onclick = () => { window.focus(); go?.run(); n.close(); };
    }
    return;
  }
  if (run.status === "failed") toast(run.error, { tone: "error", head: `${head} failed` });
  else if (run.status === "succeeded" || run.status === "skipped") toast(scanSummary(run), { tone: "ok", head, action: run.status === "succeeded" && run.new_issues?.length ? go : null });
}

const scanLabel = (name) => scans.list.find((s) => s.name === name)?.title || name;

function scanSummary(r) {
  switch (r.status) {
    case "running": return r.activity || "Running…";
    case "skipped": return r.note || "Nothing to scan";
    case "failed": return r.error || "Failed";
    case "canceled": return "Canceled";
    case "interrupted": return r.note || "Dash stopped during the scan";
  }
  const c = r.counts || {};
  const known = (c.known || 0) + (c.updated || 0);
  const parts = [`${c.new || 0} new`];
  if (known) parts.push(`${known} already known`);
  if (c.reopened) parts.push(`${c.reopened} reopened`);
  if (c.dismissed) parts.push(`${c.dismissed} dismissed`);
  return r.findings ? parts.join(", ") : "No issues found";
}

// showRunIssues opens Issues filtered to what a run added ("new"), brought
// back ("reopened") or both ("all"). With select, the ones still open (no
// task yet) are checked, ready for a bulk action.
function showRunIssues(run, which, select = false) {
  const ids = which === "reopened" ? run.reopened_issues || []
    : which === "all" ? [...(run.new_issues || []), ...(run.reopened_issues || [])]
    : run.new_issues || [];
  const what = { reopened: "Reopened", all: "Found" }[which] || "New";
  iss.filter.run = { id: run.id, ids: new Set(ids), label: `${what} · ${scanLabel(run.scan)}, ${agoText(run.started_at)}` };
  iss.filter.status = select ? "active" : "all";
  $("#issue-f-status").value = iss.filter.status;
  if (select) {
    iss.checked.clear();
    for (const i of iss.list) if (iss.filter.run.ids.has(i.id) && pickable(i)) iss.checked.add(i.id);
  }
  showView("issues");
  renderIssues();
}

const agoText = (iso) => (ago(iso) === "now" ? "just now" : `${ago(iso)} ago`);

// "in 5m", "in 3h", "in 2d"
function until(iso) {
  const s = (new Date(iso) - Date.now()) / 1000;
  if (s < 60) return "soon";
  if (s < 3600) return `in ${Math.round(s / 60)}m`;
  if (s < 86400) return `in ${Math.round(s / 3600)}h`;
  return `in ${Math.round(s / 86400)}d`;
}

// describeCron reads common cron expressions out; others stay as they are.
function describeCron(expr) {
  const days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
  const f = (expr || "").trim().split(/\s+/);
  const macro = { "@hourly": "Every hour", "@daily": "Daily at 00:00", "@midnight": "Daily at 00:00", "@weekly": "Sundays at 00:00", "@monthly": "Monthly on the 1st" }[f[0]];
  if (macro) return macro;
  if (f.length !== 5) return expr;
  const [mi, hr, dom, mon, dow] = f;
  const num = (x) => /^\d+$/.test(x);
  if (/^\*\/\d+$/.test(mi) && hr === "*" && dom === "*" && mon === "*" && dow === "*") return `Every ${mi.slice(2)} minutes`;
  if (num(mi) && hr === "*" && dom === "*" && mon === "*" && dow === "*") return `Hourly at :${mi.padStart(2, "0")}`;
  if (!num(mi) || !num(hr) || mon !== "*") return expr;
  const time = `${hr.padStart(2, "0")}:${mi.padStart(2, "0")}`;
  if (dom === "*" && dow === "*") return `Daily at ${time}`;
  if (dom === "*" && (dow === "1-5" || dow === "mon-fri")) return `Weekdays at ${time}`;
  if (dom === "*" && num(dow) && +dow <= 7) return `${days[+dow]}s at ${time}`;
  if (num(dom) && dow === "*") return `Monthly on day ${dom} at ${time}`;
  return expr;
}

function renderScanBadge() {
  const n = scans.list.filter((s) => s.running).length;
  // The side rail's, and on mobile the menu drawer's.
  for (const b of $$("#scan-badge, #menu-scan-badge")) {
    b.hidden = !n;
    b.textContent = n;
    b.title = `${plural(n, "scan")} running`;
  }
}

function renderScans() {
  renderScanBadge();
  const p = state.project;
  const intro = $("#scan-intro");
  intro.hidden = !p || !scans.loaded;
  intro.replaceChildren(scans.builtin
    ? h("span", {}, "This repository has no scan templates, so Dash's built-in scans run, next to any you write here with New scan. To share scans with your team, add them as markdown files in ", h("code", {}, `${scans.dir}/`), " (Export to repo gives you the file).")
    : h("span", {}, "Scans from ", h("code", {}, `${scans.dir}/`), " in this repository and the ones you write here. They read the code and add what they find to Issues; extra tools and schedules a repository template asks for apply once you approve them here."));
  $("#scan-new").hidden = !p || !scans.loaded;
  showRunnerNeeded($("#scan-runner-note"), scans.loaded ? p : null);
  const probs = $("#scan-problems");
  probs.hidden = !scans.problems.length;
  probs.replaceChildren(...scans.problems.map((x) => h("li", {}, h("code", {}, x.file), `: ${x.error}`)));
  $("#scan-list").replaceChildren(...(p ? scans.list.map(scanCard) : []));
  $("#scan-empty").hidden = !!p;
}

// scanSource says where a scan comes from, for its card.
const scanSource = (s) => s.source === "dash" ? "written in Dash" : s.builtin ? "built-in" : h("code", {}, s.file);

function scanCard(s) {
  if (s.shadowed_by) return shadowedScanCard(s);
  const sch = s.schedule;
  const running = s.last_run?.status === "running" && s.running ? s.last_run : null;
  const patch = (body) => api("PATCH", `/api/projects/${state.project.id}/scans/${encodeURIComponent(s.name)}`, body).then(() => loadScans());
  const editCron = attempt(async () => {
    const v = await ask({
      title: `Schedule of ${s.title}`, input: true, value: sch.cron, placeholder: "0 6 * * *", ok: "Save",
      body: `A cron expression: minute hour day month weekday, in this computer's time. E.g. "0 6 * * *" daily at 06:00, "0 7 * * 1-5" weekdays at 07:00, "@hourly".${sch.default ? ` Empty: the template's (${sch.default}).` : ""}`,
    });
    if (v === null) return;
    await patch({ schedule: v.trim(), ...(v.trim() && !sch.enabled ? { enabled: true } : {}) });
  });
  const meta = [SCAN_SCOPES[s.scope] || s.scope, s.path && s.scope !== "path" ? `in ${s.path}` : s.path, s.model, s.effort && `${s.effort} effort`].filter(Boolean).join(" · ");
  const hist = scans.history.get(s.name);
  return h("li", { class: `scan-card${running ? " running" : ""}`, "data-scan": s.name },
    h("div", { class: "scan-head" },
      h("div", { class: "scan-id" },
        h("div", { class: "scan-name" }, h("strong", {}, s.title), h("span", { class: `scan-kind kind-${s.kind}` }, SCAN_KINDS[s.kind] || s.kind)),
        h("div", { class: "scan-meta" }, meta, " · ", scanSource(s)),
        scanActions(s)),
      running
        ? ib({ type: "button", class: "btn small", onclick: attempt(() => api("POST", `/api/scan-runs/${running.id}/cancel`)) }, "stop", "Stop")
        : ib({ type: "button", class: "btn small primary", onclick: attempt(async () => {
            const run = await api("POST", `/api/projects/${state.project.id}/scans/${encodeURIComponent(s.name)}/run`);
            s.running = run.id;
            s.last_run = run;
            renderScans();
          }) }, "play", "Run now")),
    h("div", { class: "scan-sched" },
      h("label", { class: "scan-switch", title: sch.cron ? (sch.enabled ? "Turn the schedule off" : "Turn the schedule on") : "Set a schedule first" },
        h("input", { type: "checkbox", role: "switch", checked: sch.enabled, disabled: !sch.cron, onchange: attempt((e) => patch(
          // Turning on a repository schedule never approved approves the one shown.
          e.target.checked && sch.requested && sch.cron === sch.requested ? { approve_schedule: sch.requested } : { enabled: e.target.checked })) }),
        h("span", {}, "Scheduled")),
      h("button", { type: "button", class: "link scan-cron", title: sch.cron ? `${sch.cron} — change` : "Set a schedule", onclick: editCron },
        sch.cron ? describeCron(sch.cron) : "No schedule"),
      sch.enabled && s.next_run ? h("span", { class: "scan-next", title: new Date(s.next_run).toLocaleString(timeLocale) }, `next ${until(s.next_run)}`) : null,
      sch.custom ? h("button", { type: "button", class: "link scan-reset", title: `Back to the template's schedule${sch.default ? ` (${sch.default})` : ""}, off` , onclick: attempt(() => patch({ reset: true })) }, "Reset") : null,
      !sch.enabled && sch.cron && s.builtin && !sch.custom ? h("span", { class: "scan-hint" }, "suggested; off until turned on") : null),
    scanApprovals(s, patch),
    s.last_run ? scanReport(s.last_run) : h("p", { class: "scan-never" }, "Never run."),
    s.last_report && s.last_report.id !== s.last_run?.id ? scanReport(s.last_report, true) : null,
    !s.last_run ? null : h("div", { class: "scan-foot" },
      h("button", { type: "button", class: "link", "aria-expanded": String(!!hist), onclick: attempt(() => {
        if (hist) { scans.history.delete(s.name); renderScans(); } else return loadScanHistory(s.name);
      }) }, hist ? "Hide earlier runs" : "Earlier runs")),
    hist ? h("ol", { class: "scan-history" }, ...hist.filter((r) => r.id !== s.last_run?.id && r.id !== s.last_report?.id).map((r) => h("li", {}, scanReport(r, true))),
      hist.filter((r) => r.id !== s.last_run?.id && r.id !== s.last_report?.id).length ? null : h("li", { class: "scan-never" }, "No earlier runs.")) : null);
}

// shadowedScanCard is a Dash scan that doesn't run because a repository (or
// built-in) scan has its name.
function shadowedScanCard(s) {
  const by = s.shadowed_by === "built-in" ? "the built-in scan" : h("code", {}, s.shadowed_by);
  return h("li", { class: "scan-card shadowed", "data-scan": s.name },
    h("div", { class: "scan-head" },
      h("div", { class: "scan-id" },
        h("div", { class: "scan-name" }, h("strong", {}, s.title), h("span", { class: `scan-kind kind-${s.kind}` }, SCAN_KINDS[s.kind] || s.kind), h("span", { class: "scan-shadow-tag" }, "Shadowed")),
        h("div", { class: "scan-meta" }, "written in Dash"),
        scanActions(s))),
    h("p", { class: "scan-note" }, "Not used: ", by, ` is also called “${s.name}” and runs instead. Duplicate this scan under another name, or delete it.`));
}

// scanActions edit, duplicate, export or delete a scan. Only scans written
// in Dash can be edited or deleted; any can be duplicated into one.
function scanActions(s) {
  const dash = s.source === "dash";
  const url = `/api/projects/${state.project.id}/scans/${encodeURIComponent(s.name)}`;
  const del = attempt(async () => {
    if (!await ask({
      title: `Delete ${s.title}?`, danger: true, ok: "Delete scan",
      body: `The scan is removed from Dash. Its earlier runs and the issues it found (source scan:${s.name}) stay.`,
    })) return;
    await api("DELETE", url);
    scans.history.delete(s.name);
    await loadScans();
    toast(`Deleted ${s.title}`);
  });
  const exp = attempt(async () => {
    const file = `${scans.dir}/${s.name}.md`;
    const v = await ask({
      title: "Export to repo", input: true, value: s.markdown, ok: "Copy",
      body: `Save this as ${file} and commit it to share the scan with your team. Once it's merged, the repository's file is used and this one is shadowed; delete it here then.`,
    });
    if (v !== null) await copy(s.markdown, `Copied ${file}`);
  });
  return h("div", { class: "scan-actions" },
    dash ? h("button", { type: "button", class: "link", onclick: () => openScanEditor(s, true) }, "Edit") : null,
    h("button", { type: "button", class: "link", onclick: () => openScanEditor(s, false) }, "Duplicate"),
    dash && s.markdown ? h("button", { type: "button", class: "link", onclick: exp }, "Export to repo") : null,
    dash ? h("button", { type: "button", class: "link danger", onclick: del }, "Delete") : null);
}

// scanEditing is the scan the editor changes; null: it makes a new one.
let scanEditing = null;

// openScanEditor opens the scan editor: empty for a new scan, on a Dash
// scan to edit it (edit=true), or on any scan to start a copy of it.
function openScanEditor(s = null, edit = false) {
  const f = $("#scan-form");
  f.reset();
  scanEditing = edit ? s : null;
  const taken = new Set(scans.list.map((x) => x.name));
  let name = "";
  if (s && !edit) {
    for (let i = 1; !name || taken.has(name); i++) name = `${s.name}-${i === 1 ? "copy" : `copy${i}`}`;
  }
  const sch = s?.schedule;
  f.name.value = edit ? s.name : name;
  f.name.readOnly = edit;
  f.title.value = s ? (edit ? s.title : `${s.title} (copy)`) : "";
  f.kind.value = s?.kind || "custom";
  f.scope.value = s?.scope || "repo";
  f.path.value = s?.path || "";
  f.model.value = s?.model || "";
  f.effort.value = s?.effort || "";
  // Editing: the schedule that runs now (a change in the list included);
  // a copy starts from the template's.
  f.schedule.value = (edit ? sch?.cron : sch?.default) || "";
  f.tools.value = (s?.tools || []).join("\n");
  f.prompt.value = s?.prompt || "";
  $("#scan-sheet-title").textContent = edit ? `Edit ${s.title}` : s ? `Duplicate ${s.title}` : "New scan";
  const from = $("#scan-form-from");
  from.hidden = !(s && !edit);
  if (s && !edit) from.textContent = `A new scan, kept in Dash, starting from ${s.source === "dash" ? "the Dash scan" : s.builtin ? "the built-in scan" : s.file} “${s.name}”.`;
  $("#scan-sheet").showModal();
  (edit ? f.prompt : f.name).focus();
}

$("#scan-new").addEventListener("click", () => openScanEditor());
$("#scan-form").addEventListener("submit", attempt(async (e) => {
  if (e.submitter?.value !== "save") return;
  e.preventDefault(); // stays open if saving fails
  const f = e.target;
  const body = {
    name: f.name.value.trim(), title: f.title.value.trim(), kind: f.kind.value, scope: f.scope.value,
    path: f.path.value.trim(), model: f.model.value.trim(), effort: f.effort.value, schedule: f.schedule.value.trim(),
    tools: f.tools.value.split("\n").map((x) => x.trim()).filter(Boolean), prompt: f.prompt.value,
  };
  const pid = state.project.id;
  if (scanEditing) await api("PUT", `/api/projects/${pid}/scans/${encodeURIComponent(scanEditing.name)}`, body);
  else await api("POST", `/api/projects/${pid}/scans`, body);
  const what = scanEditing ? "Saved" : "Created";
  $("#scan-sheet").close();
  await loadScans();
  toast(`${what} ${body.title || body.name}`, { tone: "ok" });
}));

// scanApprovals shows what a repository template asks for that the user
// hasn't approved: tools beyond read-only (it runs read-only until then) and
// its schedule (off, or the approved one, until then). Anyone who can merge
// to the repository can change a template, so Dash asks before it runs a
// shell or runs on a timer.
function scanApprovals(s, patch) {
  const sch = s.schedule;
  const askTools = s.tools?.length && !s.tools_approved;
  const askSched = !!sch.requested;
  if (!askTools && !askSched) return null;
  const approveTools = attempt(async () => {
    if (!await ask({
      title: `Let ${s.title} use these tools?`,
      body: `${s.file} asks for: ${s.tools.join(", ")}. Scans run on this computer; tools such as Bash run commands here. Approve only if you trust this template. If it asks for other tools later, it goes back to read-only until you approve again.`,
      ok: "Approve tools",
    })) return;
    await patch({ approve_tools: s.tools });
  });
  const changed = sch.enabled && sch.cron !== sch.requested;
  return h("div", { class: "scan-approve", role: "note" },
    askTools ? h("p", {},
      h("span", {}, s.approved_tools?.length ? "The template now asks for other tools: " : "The template asks for tools beyond read-only: ",
        h("code", {}, s.tools.join(", ")), ". It runs read-only until you approve them."),
      h("button", { type: "button", class: "btn small", onclick: approveTools }, "Approve tools")) : null,
    askSched ? h("p", {},
      h("span", {}, changed
        ? `The template's schedule changed to ${describeCron(sch.requested)} (${sch.requested}); it keeps running ${describeCron(sch.cron)} until you approve the new one.`
        : `The template asks to run ${describeCron(sch.requested)} (${sch.requested}); it stays off until you turn it on.`),
      h("button", { type: "button", class: "btn small", onclick: attempt(() => patch({ approve_schedule: sch.requested })) }, changed ? "Approve new schedule" : "Approve and turn on")) : null);
}

// runIssueStatus sorts the issues a run added or reopened by what became of
// them since: still open, fixed (resolved), taken up in a task, dismissed or
// deleted. Without the project's issues loaded, everything counts as open.
function runIssueStatus(r, which) {
  const ids = (which === "reopened" ? r.reopened_issues : r.new_issues) || [];
  const out = { open: 0, task: 0, fixed: 0, dismissed: 0, gone: 0, urgent: 0 };
  for (const id of ids) {
    if (!iss.loaded) { out.open++; continue; }
    const i = iss.list.find((x) => x.id === id);
    if (!i) { out.gone++; continue; }
    const k = { open: "open", task_created: "task", resolved: "fixed", dismissed: "dismissed" }[i.status] || "open";
    out[k]++;
    if (triageable(i) && (i.severity === "critical" || i.severity === "high")) out.urgent++;
  }
  // Runs from before the ids were kept: trust the counts.
  if (!ids.length) out.open = which === "reopened" ? r.counts?.reopened || 0 : r.counts?.new || 0;
  return out;
}

function scanReport(r, compact = false) {
  const c = r.counts || {};
  const known = (c.known || 0) + (c.updated || 0);
  const icon = { running: null, succeeded: "check", failed: "x", skipped: "redo", canceled: "stop", interrupted: "reload" }[r.status];
  const label = { running: "Running", succeeded: "Done", failed: "Failed", skipped: "Skipped", canceled: "Canceled", interrupted: "Interrupted" }[r.status] || r.status;
  const link = (n, text, which) => n ? h("button", { type: "button", class: `scan-count link${which === "new" ? " new" : ""}`, title: "Show them in Issues", onclick: () => showRunIssues(r, which) }, `${n} ${text}`) : null;
  const bits = [
    agoText(r.started_at),
    r.trigger === "schedule" ? "scheduled" : r.trigger === "resume" ? "↻ resumed after restart" : "by hand",
    r.commit ? (r.incremental && r.since ? `${r.since.slice(0, 7)}…${r.commit.slice(0, 7)}` : r.commit.slice(0, 7)) : null,
    r.finished_at ? `${Math.max(1, Math.round((new Date(r.finished_at) - new Date(r.started_at)) / 1000))}s` : null,
    r.cost_usd ? `≈$${r.cost_usd.toFixed(2)}` : null,
    r.invalid ? `${r.invalid} dropped` : null,
  ].filter(Boolean);
  let body;
  if (r.status === "succeeded" && r.findings) {
    // The counts are what the run found; what has been done about its new
    // and reopened issues since is read from the issues as they are now.
    const nw = runIssueStatus(r, "new"), ro = runIssueStatus(r, "reopened");
    const since = (k, text, title) => {
      const n = nw[k] + ro[k];
      return n ? h("button", { type: "button", class: "scan-count link muted", title, onclick: () => showRunIssues(r, nw[k] ? "new" : "reopened") }, `${n} ${text}`) : null;
    };
    const urgent = iss.loaded && (r.new_issues?.length || r.reopened_issues?.length) ? nw.urgent + ro.urgent : r.urgent;
    // What "Select all" would check: this run's issues that are still open (not in a task).
    const selectable = iss.loaded && (r.new_issues?.length || r.reopened_issues?.length) ? nw.open + ro.open : 0;
    body = h("p", { class: "scan-counts" },
      link(nw.open, "new", "new") || h("span", { class: "scan-count" }, "0 new"),
      known ? h("span", { class: "scan-count" }, `${known} already known`) : null,
      link(ro.open, "reopened", "reopened"),
      c.dismissed ? h("span", { class: "scan-count muted", title: "Found again, but you dismissed them; they stay dismissed" }, `${c.dismissed} dismissed`) : null,
      since("task", "in a task", "New or reopened issues from this run that a task is working on"),
      since("fixed", "fixed", "New or reopened issues from this run that have been fixed since"),
      since("dismissed", "dismissed since", "New or reopened issues from this run that were dismissed since"),
      nw.gone + ro.gone ? h("span", { class: "scan-count muted", title: "New or reopened issues from this run that were deleted since" }, `${nw.gone + ro.gone} deleted`) : null,
      urgent ? h("span", { class: "sev sev-high scan-urgent", title: "New or reopened issues of critical or high severity that are still open" }, `${urgent} urgent`) : null,
      selectable ? ib({ type: "button", class: "btn small scan-select", title: "Open the new and reopened issues from this run that are still open, all selected, to create tasks for them or dismiss them", onclick: () => showRunIssues(r, "all", true) }, "checks", `Select all ${selectable}`) : null);
  } else {
    body = h("p", { class: `scan-msg${r.status === "failed" ? " error" : ""}` }, r.status === "running" ? h("span", { class: "spinner", "aria-hidden": "true" }) : null, scanSummary(r));
  }
  return h("div", { class: `scan-report st-${r.status}${compact ? " compact" : ""}` },
    h("div", { class: "scan-report-head" },
      h("span", { class: "scan-status" }, icon ? ico(icon) : null, label),
      h("span", { class: "scan-when", title: r.invalid ? "Dropped: findings the scan returned that were not valid; see the log" : null }, bits.join(" · ")),
      h("a", { class: "link scan-log", href: on(here(), `/api/scan-runs/${r.id}/log`), target: "_blank", rel: "noopener" }, "Log")),
    body,
    r.answer ? h("details", { class: "scan-answer" }, h("summary", {}, "The agent's answer"), h("pre", {}, r.answer)) : null,
    r.note && r.status === "succeeded" ? h("p", { class: "scan-note" }, r.note) : null,
    r.resumed_as ? h("p", { class: "scan-note" }, `↻ Resumed as ${r.resumed_as}`) : null,
    r.resumed_from ? h("p", { class: "scan-note" }, `Restarts run ${r.resumed_from}, which Dash's restart interrupted`) : null);
}

$("#issue-f-run").addEventListener("click", () => { iss.filter.run = null; iss.filter.status = "active"; $("#issue-f-status").value = "active"; renderIssues(); });

// ------------------------------------------------------------------ vim keys
// Normal mode is the default; typing in a field or the terminal is insert
// mode. Esc (Ctrl-] in the terminal) returns to normal mode.
const VIEWS = ["board", "issues", "scans", "run", "history", "files"];
const keys = { active: false, count: 0, pending: "", cur: { lane: 0, row: 0 } };

const BOUND = /^(:|\?|gt|gT|gg|gx|gb|gi|gS|gc|gs|gh|gf|G|F|u|p|c|\[|q|Escape|y|Y|A|n|N|j|k|h|l|w|b|o|O|s|x|a|r|e|E|\+|-|K|J|\*|t|T|!|dd|i|I|R|D|\/|Enter| |Arrow(Up|Down|Left|Right)|ctrl\+[dufb])$/;
const isTyping = (el) => el && (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName) || el.closest?.(".xterm"));
const openDialog = () => document.querySelector("dialog[open]");

function setMode() {
  const el = $("#kbd-status");
  const typing = isTyping(document.activeElement);
  const mode = document.activeElement?.id === "cmd-input" ? "command" : typing ? "insert" : "normal";
  el.dataset.mode = mode;
  el.textContent = mode.toUpperCase() +(keys.count || keys.pending ? `  ${keys.count || ""}${keys.pending}` : "");
}
document.addEventListener("focusin", setMode);
document.addEventListener("focusout", () => setTimeout(setMode));
// Mouse or touch hides the keyboard cursor; a key brings it back.
document.addEventListener("pointerdown", () => { if (keys.active) { keys.active = false; renderBoard(); } });

function laneCount() { return LANES.length; }
function laneTodos(li) { return laneItems()[LANES[li].key] || []; }
function cursorTodo() { return laneTodos(keys.cur.lane)[keys.cur.row] || null; }
// Minimized lanes (desktop only) and hidden ones are skipped by lane navigation.
function laneSkipped(li) { return (desktop.matches && state.collapsed.has(LANES[li].key)) || laneHidden(LANES[li].key); }
// With auto approve, finished work skips Review; the lane only shows while
// something still waits there (failing tests, a merge that came back).
function laneHidden(key) {
  return key === "review" && !!state.project?.auto_approve && ![...state.todos.values()].some((t) => ["review", "failed"].includes(t.status));
}
function stepLane(lane, d) {
  const step = Math.sign(d);
  for (let li = lane + step, left = Math.abs(d); li >= 0 && li < laneCount(); li += step) {
    if (!laneSkipped(li)) { lane = li; if (!--left) break; }
  }
  return lane;
}

function moveCursor(lane, row) {
  lane = Math.max(0, Math.min(laneCount() - 1, lane));
  const n = laneTodos(lane).length;
  keys.cur = { lane, row: Math.max(0, Math.min(n - 1, row)) };
  keys.active = true;
  if (!desktop.matches) state.lane = LANES[lane].key; // mobile shows one lane
  renderBoard();
  ($(".todo.cursor") || $(".col.cursor"))?.scrollIntoView({ block: "nearest", inline: "nearest" });
}

// The element j/k and Ctrl-d/u scroll in the current context.
function scroller() {
  if (state.detail) return $(".detail-body");
  return desktop.matches ? $(".view.active") : document.scrollingElement;
}

function scrollBy(el, how, n) {
  const page = el.clientHeight || innerHeight;
  const delta = { j: 48, k: -48, "ctrl+d": page / 2, "ctrl+u": -page / 2, "ctrl+f": page * 0.9, "ctrl+b": -page * 0.9 }[how];
  if (how === "gg") el.scrollTo({ top: 0 });
  else if (how === "G") el.scrollTo({ top: el.scrollHeight });
  else el.scrollBy({ top: delta * n });
}

// What Enter does to a task: approve one in review, enqueue a draft.
function enterKey(t) { return { review: "a", draft: "s" }[t.status]; }

// Actions on a todo; shared by the board cursor and the open detail view.
async function todoKey(t, k) {
  const post = (verb, body, msg) => api("POST", `/api/todos/${t.id}/${verb}`, body).then(() => toast(msg));
  switch (k) {
    case "s": return post("enqueue", null, "Added to queue");
    case "x": return post("cancel", null, t.status === "in_progress" ? "Stopping" : "Moved to drafts");
    case "z": return t.paused ? post("resume", null, "Resumed") : post("pause", null, t.status === "in_progress" ? "Pausing" : "Paused");
    case "a": return post("approve", null, "Approved — merging");
    case "r": return reworkTodo(t);
    case "u": return revertTodo(t);
    case "gx":
      if (!t.pr) throw new Error("This task has no pull request.");
      return window.open(t.pr.url, "_blank", "noopener");
    case "e": return openTodoForm(t);
    case "+": return api("PATCH", `/api/todos/${t.id}`, { priority: t.priority - 1 });
    case "-": return api("PATCH", `/api/todos/${t.id}`, { priority: t.priority + 1 });
    case "t": return previewTodo(t);
    case "!": return openShell({ todo_id: t.id }, t.runner);
    case "dd":
      if (await ask({ title: `Delete "${title(t)}"?`, body: "Its worktree and branch are removed too. This can't be undone.", ok: "Delete", danger: true })) {
        await api("DELETE", `/api/todos/${t.id}`);
        if (state.detail === t.id) closeDetail();
        toast("Task deleted");
      }
      return;
  }
  if (k === "T") return api("POST", `/api/todos/${t.id}/test`).then(() => toast("Running tests…"));
  if (k === "Y") return api("POST", `/api/todos/${t.id}/duplicate`).then(() => toast("Duplicated as a draft"));
  if (k === "E") return api("POST", `/api/todos/${t.id}/open`).then(() => toast("Opening in your editor"));
  return false; // not a todo key
}

// y / A / n answer the permission request in view: the open todo's, else the oldest.
async function permKey(k) {
  const p = state.perms.find((x) => x.todo_id === state.detail) || (!state.detail && state.perms[0]);
  if (!p) return false;
  const decision = { y: "allow", A: "always", n: "deny" }[k];
  await api("POST", `/api/permissions/${p.id}`, { decision });
  toast(decision === "deny" ? "Denied" : decision === "always" ? `${p.tool} always allowed in this project` : "Allowed");
}

async function runCommand(line) {
  line = line.trim().replace(/^:/, "");
  if (!line) return;
  if (/^\d+$/.test(line)) { moveCursor(keys.cur.lane, Number(line) - 1); return; }
  const [name, ...rest] = line.split(/\s+/);
  const arg = rest.join(" ");
  const need = () => { if (!state.project) throw new Error("Select a project first (p)."); return state.project; };
  switch (name) {
    case "q": case "q!": case "close": closeDetail(); openDialog()?.close(); return;
    case "b": case "board": return showView("board");
    case "c": case "chat": return toggleChatPane();
    case "pin": case "unpin": return togglePin();
    case "fs": case "full": case "fullscreen": return toggleFullscreen();
    case "run": case "!": case "sh": case "shell":
      if (!arg) return showView("run");
      need(); return openShell({ command: arg });
    case "ps": case "procs": return showView("run");
    case "try": need(); return openTry();
    case "history": case "graph": case "tree": return showView("history");
    case "p": case "project": {
      if (!arg) return openProjects();
      const [pn, mn = ""] = arg.toLowerCase().split("@");
      const p = state.projects.find((x) => x.name.toLowerCase().startsWith(pn) && x.machine.toLowerCase().startsWith(mn));
      if (!p) throw new Error(`No project matching "${arg}".`);
      return selectProject(p);
    }
    case "np": case "newproject": {
      const [pname, path = ""] = arg.split(/\s+/, 2);
      if (!pname) throw new Error("Usage: :newproject <name> [path]");
      const p = await api("POST", "/api/projects", { name: pname, path });
      const machine = state.project?.machine || state.machines?.[0]?.name;
      await loadProjects();
      await selectProject(state.projects.find((x) => x.id === p.id && x.machine === machine));
      return toast(`Created ${p.name}`);
    }
    case "ac": case "addclone": {
      const [path, pname = ""] = arg.split(/\s+/, 2);
      if (!path) throw new Error("Usage: :addclone <path> [name]");
      const p = await api("POST", "/api/projects", { existing: true, path, name: pname });
      const machine = state.project?.machine || state.machines?.[0]?.name;
      await loadProjects();
      await selectProject(state.projects.find((x) => x.id === p.id && x.machine === machine));
      return toast(`Added ${p.name}`);
    }
    case "new": case "o":
      need(); openTodoForm(); if (arg) $("#todo-form").prompt.value = arg; return;
    case "todo": case "task":
      if (!arg) throw new Error("Usage: :task <instructions>");
      await api("POST", `/api/projects/${need().id}/todos`, { prompt: arg, enqueue: true });
      return toast("Added to queue");
    case "cleanup": case "clean": need(); return cleanup();
    case "ci": case "builds": return openCI();
    case "push": need(); return pushDone();
    case "pause": case "resume":
      state.usage = await api("POST", `/api/queue/${name}`);
      renderUsage();
      return toast(name === "pause" ? "Queue paused" : "Queue resumed");
    case "usage": renderUsage(); return $("#usage-sheet").showModal();
    case "settings": need(); return openSettings();
    case "prefs": case "preferences": return openPrefs();
    case "connector": case "connect": return openConnector();
    case "perms": case "permissions":
      if (!state.perms.length) return toast("No permission requests waiting");
      showView("board"); closeDetail();
      return $("#perm-banner").scrollIntoView({ block: "nearest" });
    case "notify": case "notifications": return toggleNotifications();
    case "vim": return toggleVim();
    case "list": case "invisibles": return toggleInvisibles();
    case "clear": {
      const c = activeChat();
      if (!c) throw new Error("Pick a project first.");
      return c.clear();
    }
    case "help": case "h": return $("#keys-sheet").showModal();
    case "logout": return logout();
    case "e": case "e!": case "refresh": return loadProjects();
  }
  throw new Error(`Not a command: ${name}. Press ? for help.`);
}

function openCommandLine() {
  const input = $("#cmd-input");
  input.value = "";
  input.focus();
}
$("#cmd-input").addEventListener("blur", (e) => { e.target.value = ""; });
$("#cmd-form").addEventListener("submit", (e) => {
  e.preventDefault();
  const line = $("#cmd-input").value;
  $("#cmd-input").blur();
  attempt(runCommand)(line);
});

// ------------------------------------------------------------------ palette
// Ctrl-k: one search over commands, projects and the current project's todos.
// A leading > limits it to commands, @ to projects, # to todos.
const palette = { items: [], sel: 0 };

// Every word must appear in the text, as a substring (best) or in order.
function fuzzyScore(text, q) {
  text = text.toLowerCase();
  let total = 0;
  for (const w of q.toLowerCase().split(/\s+/).filter(Boolean)) {
    const i = text.indexOf(w);
    if (i >= 0) { total += 100 - Math.min(i, 50) + (i === 0 || /\W/.test(text[i - 1]) ? 40 : 0); continue; }
    let from = 0, prev = -2, s = 0;
    for (const c of w) {
      const j = text.indexOf(c, from);
      if (j < 0) return -1;
      s += j === prev + 1 ? 3 : 1;
      prev = j; from = j + 1;
    }
    total += s;
  }
  return total;
}

function paletteCommands() {
  const p = state.project;
  const go = (view) => () => { closeDetail(); showView(view); };
  const serve = techFor("web:run"), deploy = techFor("task:deploy");
  return [
    p && ["New task", "plus", () => openQuickAdd(), "n", "add create todo quick"],
    p && ["New task with all options", "plus", () => openTodoForm(), "N", "add create todo full form title priority dependencies attachments"],
    ["Board", "flag", go("board"), "gb", "view lanes"],
    ["Issues", "bug", go("issues"), "gi", "bugs vulnerabilities problems triage scan"],
    ["Scans", "scan", go("scans"), "gS", "scan security review dependency audit schedule cron"],
    ["Toggle chat", "comment", () => toggleChatPane(), "gc", "chat open close claude ask project general"],
    [pane.pinned ? "Unpin chat" : "Pin chat", "pin", togglePin, ":pin", "pin unpin chat overlay dock"],
    fsSupported && [isFullscreen() ? "Exit fullscreen" : "Fullscreen", isFullscreen() ? "fs-exit" : "fs", () => toggleFullscreen(), "F", "fullscreen full screen maximize kiosk"],
    ["Shell", "terminal", go("run"), "gs", "run terminal processes view"],
    ["History", "log", go("history"), "gh", "git graph tree commits view"],
    ["Files", "code", go("files"), "gf", "browse edit source code tree editor"],
    ["Switch project", "repo", openProjects, "p", "projects"],
    ["New project", "plus", () => openNewProject(), "", "create add local repository runner github"],
    p && ["Project settings", "settings", openSettings, ":settings", "configure commands"],
    p?.run_command && [serve.label || "Run", serve.icon || "play", () => startProc({ kind: "web", preset: "run" }), "R", `run web ${serve.icon || ""}`],
    p?.test_command && ["Run tests", "check", () => startProc({ kind: "task", preset: "test" }), "T", "test"],
    p?.deploy_command && [deploy.label || "Deploy", deploy.icon || "rocket", () => startProc({ kind: "task", preset: "deploy" }), "D", `release ship ${deploy.icon || ""}`],
    p && !shellBlocked(p) && ["Open a shell", "terminal", () => openShell(), "!", "terminal pty"],
    p && state.unpushed > 0 && ["Push merged work", "push", pushDone, ":push", "git"],
    p && ["Clean up", "trash", cleanup, ":cleanup", "worktrees branches"],
    p && ["Delete project…", "trash", openDeleteProject, "", "remove repo clone github"],
    ["Builds", "checks", openCI, ":ci", "ci github actions"],
    ["Claude usage", "clock", () => { renderUsage(); $("#usage-sheet").showModal(); }, ":usage", "limits"],
    state.usage && [state.usage.paused ? "Resume the queue" : "Pause the queue", state.usage.paused ? "play" : "pause", () => runCommand(state.usage.paused ? "resume" : "pause"), "", "queue"],
    ["Permission requests", "eye", () => runCommand("perms"), ":perms", "approvals allow deny"],
    state.runners && ["Runners", "computer", openRunners, ":runners", "computers machines dash runner add install revoke"],
    ["Preferences", "prefs", openPrefs, ":prefs", "preferences vim invisibles whitespace notifications browser"],
    ["Connect Claude", "plug", openConnector, ":connector", "claude.ai connector mcp mobile app remote oauth"],
    [notifyLabel(), notifyOn() ? "bell-off" : "bell", toggleNotifications, ":notify", "notifications"],
    [vimOn() ? "Turn off vim keys in the editor" : "Turn on vim keys in the editor", "code", toggleVim, ":vim", "vim keybindings prompt editor"],
    [invisiblesOn() ? "Hide invisible characters in the editor" : "Show invisible characters in the editor", "code", toggleInvisibles, ":list", "invisibles whitespace tabs spaces trailing"],
    desktop.matches && [sideCollapsed() ? "Expand sidebar" : "Collapse sidebar", "minimize", () => setSideCollapsed(!sideCollapsed()), "[", "sidebar"],
    ["Refresh projects", "redo", loadProjects, ":refresh", "reload"],
    ["Keyboard shortcuts", "code", () => $("#keys-sheet").showModal(), "?", "help keys"],
    ["Log out", "logout", logout, "", "sign out"],
  ].filter(Boolean).map(([label, icon, run, keys, words]) => ({ kind: "Command", label, icon, run, keys, text: `${label} ${words}` }));
}

function paletteProjects() {
  return state.projects.filter((p) => projectKey(p) !== projectKey(state.project)).map((p) => ({
    kind: "Project", label: p.name, icon: "repo", hint: grouped() ? projectWhere(p) : baseBranch(p),
    text: `${p.name} ${p.machine} ${projectWhere(p)} ${p.path}`, run: () => selectProject(p),
  }));
}

// Every todo, lane by lane, regardless of the board's filter or hidden old ones.
function paletteTodos() {
  const all = [...state.todos.values()];
  return LANES.flatMap((l) => all.filter((t) => l.statuses.includes(t.status)).sort(byPriority).map((t) => ({
    kind: "Task", label: title(t), icon: "draft", hint: t.paused ? "Paused" : STATUS_LABEL[t.status] || t.status,
    text: `${title(t)} ${t.prompt} ${t.id} ${STATUS_LABEL[t.status] || ""}`, run: () => { showView("board"); return openDetail(t.id); },
  })));
}

function paletteResults(raw) {
  const mode = { ">": "Command", "@": "Project", "#": "Task" }[raw[0]];
  const q = (mode ? raw.slice(1) : raw).trim();
  const sources = { Command: paletteCommands, Project: paletteProjects, Task: () => (state.project ? paletteTodos() : []) };
  const pools = (mode ? [mode] : ["Command", "Project", "Task"]).map((k) => sources[k]());
  let out;
  if (!q) out = pools.flatMap((p) => p.slice(0, mode ? 200 : 8));
  else {
    out = pools.flat().map((it) => {
      const s = fuzzyScore(it.label, q);
      return { it, s: s >= 0 ? s * 2 : fuzzyScore(it.text, q) };
    }).filter((x) => x.s >= 0).sort((a, b) => b.s - a.s).slice(0, 60).map((x) => x.it);
  }
  if (q && !mode && state.project) {
    out.push(
      { kind: "Action", label: `New task: ${q}`, icon: "plus", run: () => { openTodoForm(); $("#todo-form").prompt.value = q; promptEditor.render(); draft.changed(); } },
      { kind: "Action", label: `Ask the project chat: ${q}`, icon: "comment", run: () => { const c = projectChatFor(state.project).chat; askChat(c.input, c.input.form, q, () => toggleChatPane(true, "project")); } },
    );
  }
  if (q && !mode) out.push({ kind: "Action", label: `Ask Claude: ${q}`, icon: "spark", run: () => askChat(chat.input, $("#chat-form"), q, () => toggleChatPane(true, "general")) });
  return out;
}

function askChat(input, form, q, show) {
  show();
  input.value = q;
  input.dispatchEvent(new Event("input"));
  form.requestSubmit();
}

function renderPalette() {
  const list = $("#palette-list");
  const input = $("#palette-input");
  palette.sel = Math.max(0, Math.min(palette.items.length - 1, palette.sel));
  let group = null;
  const rows = [];
  palette.items.forEach((it, i) => {
    if (!input.value.trim() && it.kind !== group) rows.push(h("li", { class: "palette-group", role: "presentation" }, `${it.kind}s`));
    group = it.kind;
    rows.push(h("li", {
      id: `palette-${i}`, role: "option", class: "palette-item", "aria-selected": String(i === palette.sel),
      onmousemove: () => { if (palette.sel !== i) { palette.sel = i; renderPalette(); } },
      onclick: () => runPalette(i),
    }, ico(it.icon), h("span", { class: "palette-label" }, it.label),
    it.hint ? h("span", { class: "palette-hint" }, it.hint) : null,
    it.keys ? h("kbd", {}, it.keys) : input.value.trim() ? h("span", { class: "palette-kind" }, it.kind) : null));
  });
  list.replaceChildren(...(rows.length ? rows : [h("li", { class: "palette-empty", role: "presentation" }, "No matches")]));
  if (palette.items.length) input.setAttribute("aria-activedescendant", `palette-${palette.sel}`);
  else input.removeAttribute("aria-activedescendant");
  $(`#palette-${palette.sel}`)?.scrollIntoView({ block: "nearest" });
}

function updatePalette() {
  palette.items = paletteResults($("#palette-input").value);
  palette.sel = 0;
  renderPalette();
}

function openPalette(prefill = "") {
  setPicker(false);
  setMenu(false);
  const input = $("#palette-input");
  input.value = prefill;
  updatePalette();
  $("#palette").showModal();
  input.focus();
}

function runPalette(i) {
  const it = palette.items[i];
  if (!it) return;
  $("#palette").close();
  attempt(it.run)();
}

$("#palette-input").addEventListener("input", updatePalette);
$("#palette-input").addEventListener("keydown", (e) => {
  const step = { ArrowDown: 1, ArrowUp: -1 }[e.key] ?? (e.ctrlKey && { n: 1, p: -1 }[e.key]);
  const page = { PageDown: 8, PageUp: -8 }[e.key];
  if (step || page) {
    const n = palette.items.length;
    if (n) palette.sel = page ? palette.sel + page : (palette.sel + step + n) % n;
    renderPalette();
  } else if (e.key === "Enter" && !e.isComposing) runPalette(palette.sel);
  else return;
  e.preventDefault();
});
// A click on the backdrop of any modal closes it. The backdrop's clicks land on
// the dialog itself, outside its box. Both press and release must be outside,
// so dragging a text selection out of a field doesn't close the sheet.
// close("cancel") like a Cancel button: sheets save only on their own values.
const outsideDialog = (d, e) => {
  if (e.target !== d || !d.open) return false;
  const r = d.getBoundingClientRect();
  return e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom;
};
let backdropDown = null;
document.addEventListener("pointerdown", (e) => { backdropDown = e.target instanceof HTMLDialogElement && outsideDialog(e.target, e) ? e.target : null; });
document.addEventListener("click", (e) => {
  const d = backdropDown;
  backdropDown = null;
  if (d && outsideDialog(d, e)) d.close("cancel");
});
$("#palette-open").addEventListener("click", () => openPalette());
// Ctrl-k (⌘K on a Mac) works everywhere but the terminal, even while typing.
document.addEventListener("keydown", (e) => {
  if (!(e.ctrlKey || e.metaKey) || e.altKey || e.shiftKey || e.key.toLowerCase() !== "k" || e.target.closest?.(".xterm")) return;
  const d = openDialog();
  if (d && d.id !== "palette") return;
  e.preventDefault();
  e.stopPropagation();
  d ? d.close() : openPalette();
}, true);

document.addEventListener("keydown", (e) => {
  if (e.metaKey || e.altKey || e.isComposing) return;
  const target = e.target;

  // Insert mode: only Esc (leave) is ours; Ctrl-] is handled by the terminal.
  if (isTyping(target)) {
    if (e.key === "Escape" && !target.closest("dialog")) { target.blur(); setMode(); e.preventDefault(); }
    return;
  }
  if (openDialog()) return; // dialogs handle their own keys (Esc closes)

  let k = e.key;
  if (e.ctrlKey) {
    if (!["d", "u", "f", "b"].includes(k)) return;
    k = `ctrl+${k}`;
  }
  if (k === "Shift" || k === "Control") return;
  // Tab moves between the sections and projects lists; elsewhere it stays native.
  if (k === "Tab" && sidebarList(target)) {
    e.preventDefault();
    keys.count = 0; keys.pending = "";
    sidebarList(target) === SECTIONS ? openProjects() : openSections();
    setMode();
    return;
  }
  // Keyboard users activating a focused control keep the browser's behaviour
  // (except sections, which also close the open todo and leave the list).
  // Enter on a focused Review card approves it, like its Approve chip;
  // on a Draft card it enqueues, like its Enqueue chip.
  const card = k === "Enter" && state.todos.get(target.closest?.("button.todo.s-review, button.todo.s-draft")?.dataset.id);
  if (card && enterKey(card)) {
    e.preventDefault();
    attempt(todoKey)(card, enterKey(card));
    return;
  }
  if ((k === "Enter" || k === " ") && target.closest?.("button, a, summary, input, [role=tab]") && sidebarList(target) !== SECTIONS) return;

  // Counts: 5j, 10G …
  if (/^[0-9]$/.test(k) && !(k === "0" && !keys.count) && !keys.pending) {
    keys.count = keys.count * 10 + Number(k);
    setMode();
    return;
  }
  const n = Math.max(1, keys.count);
  const hadCount = keys.count > 0;
  keys.count = 0;
  if (keys.pending) {
    k = keys.pending + k;
    keys.pending = "";
  } else if (["g", "d"].includes(k)) {
    keys.pending = k;
    setMode();
    return;
  }
  setMode();
  if (!BOUND.test(k)) return; // leave Tab, browser shortcuts etc. alone
  e.preventDefault();
  attempt(handleNormal)(k, n, hadCount);
});

// Sidebar lists: o focuses the sections, p the projects (in the phone menu),
// Tab switches between them. j/k move, Enter opens the focused item, Esc, q
// or l leave the list.
const SECTIONS = ".nav > button[data-view]";
const PROJECTS = "#side-project-list .side-project";
function sidebarList(el) {
  if (el?.matches?.(SECTIONS)) return SECTIONS;
  if (el?.closest?.("#side-project-list")) return PROJECTS;
  return null;
}

function openSections() {
  setMenu(false);
  $(`.nav > button[data-view="${state.view}"]`)?.focus();
}

function openSection(name) {
  closeDetail();
  document.activeElement?.blur();
  showView(name);
  setMode();
}

function sidebarKey(k, n, hadCount) {
  const list = sidebarList(document.activeElement);
  const btns = [...document.querySelectorAll(list)];
  const i = btns.indexOf(document.activeElement);
  const go = (j) => btns[Math.max(0, Math.min(btns.length - 1, j))]?.focus();
  switch (k) {
    case "j": case "ArrowDown": return go(i + n);
    case "k": case "ArrowUp": return go(i - n);
    case "gg": return go(hadCount ? n - 1 : 0);
    case "G": return go(hadCount ? n - 1 : Infinity);
    case "Enter": case " ":
      if (list === SECTIONS) return openSection(document.activeElement.dataset.view);
      break;
    case "Escape": case "q": case "l": document.activeElement.blur(); setMenu(false); setMode(); return;
  }
  return false;
}

async function handleNormal(k, n, hadCount) {
  if (sidebarList(document.activeElement) && sidebarKey(k, n, hadCount) !== false) return;
  // Global keys.
  switch (k) {
    case ":": return openCommandLine();
    case "?": return $("#keys-sheet").showModal();
    case "gt": return showView(VIEWS[(VIEWS.indexOf(state.view) + n) % VIEWS.length]);
    case "gT": return showView(VIEWS[(VIEWS.indexOf(state.view) - n + VIEWS.length * n) % VIEWS.length]);
    case "gb": return showView("board");
    case "gc": return toggleChatPane();
    case "c": return toggleChatPane(true, "project");
    case "gs": return showView("run");
    case "gh": return showView("history");
    case "gf": return showView("files");
    case "gi": return showView("issues");
    case "gS": return showView("scans");
    case "p": return openProjects();
    case "J": case "K": return stepProject(k === "J" ? n : -n);
    case "[": return desktop.matches && setSideCollapsed(!sideCollapsed());
    case "F": return toggleFullscreen();
    case "o": return openSections();
    case "Escape": case "q":
      if (menuOpen()) return setMenu(false);
      if (k === "Escape" && pane.open && paneOverlays()) return toggleChatPane(false);
      if (state.detail) return closeDetail();
      return;
    case "y": case "A":
      if (await permKey(k) === false) toast("No permission request waiting");
      return;
    case "n": case "N":
      // n answers "deny" only when a permission request is in view; otherwise
      // n is a new task (quick sheet) and N one with all options (full form).
      if (k === "n" && state.perms.length && (!state.detail || state.perms.some((p) => p.todo_id === state.detail))) return permKey("n");
      if (!state.project) return;
      return k === "n" ? openQuickAdd() : openTodoForm();
    case "/":
      if (state.project) return openPalette("#");
      break;
  }

  // Detail view.
  if (state.detail) {
    const t = state.todos.get(state.detail);
    if (["j", "k", "ctrl+d", "ctrl+u", "ctrl+f", "ctrl+b", "gg", "G"].includes(k)) return scrollBy(scroller(), k, n);
    if (["h", "l"].includes(k)) {
      const panes = ["timeline", "diff"];
      state.pane = panes[(panes.indexOf(state.pane) + (k === "l" ? 1 : panes.length - 1)) % panes.length];
      return renderPane();
    }
    if (state.pane === "timeline" && k === "i") return todoChat.input.focus();
    if (t && k === "D" && pv.todo === t.id) return startDraw();
    if (t && k === "Enter" && enterKey(t)) return todoKey(t, enterKey(t));
    if (t) await todoKey(t, k);
    return;
  }

  switch (state.view) {
    case "board": {
      if (!state.project) return;
      const { lane, row } = keys.cur;
      switch (k) {
        case "j": case "ArrowDown": return moveCursor(lane, keys.active ? row + n : row);
        case "k": case "ArrowUp": return moveCursor(lane, row - n);
        case "h": case "ArrowLeft": return moveCursor(stepLane(lane, -n), row);
        case "l": case "ArrowRight": return moveCursor(stepLane(lane, n), row);
        case "gg": return moveCursor(lane, hadCount ? n - 1 : 0);
        case "G": return moveCursor(lane, hadCount ? n - 1 : Infinity);
        case "w": case "b": {
          const step = k === "w" ? 1 : -1;
          for (let li = lane + step; li >= 0 && li < laneCount(); li += step) {
            if (laneTodos(li).length && !laneSkipped(li)) return moveCursor(li, 0);
          }
          return;
        }
        case "Enter": case "Space": case " ": {
          const t = cursorTodo();
          if (t && k === "Enter" && enterKey(t)) return todoKey(t, enterKey(t));
          if (t) return openDetail(t.id);
          return;
        }
        case "a": return openQuickAdd();
      }
      const t = cursorTodo();
      if (t) await todoKey(t, k);
      return;
    }
    case "run": {
      const cur = state.procs.find((p) => p.id === attached);
      switch (k) {
        case "i": case "a": case "Enter": return term.focus();
        case "x": if (cur?.running) { await api("DELETE", `/api/processes/${cur.id}`); toast("Stopping"); } return;
        case "R": return startProc({ kind: "web", preset: "run" });
        case "T": return startProc({ kind: "task", preset: "test" });
        case "D": return startProc({ kind: "task", preset: "deploy" });
        case "!": return openShell();
      }
      return;
    }
    case "history":
      if (["j", "k", "ctrl+d", "ctrl+u", "ctrl+f", "ctrl+b", "gg", "G"].includes(k)) return scrollBy(scroller(), k, n);
  }
}

// Forms: Ctrl-Enter adds to the queue, Ctrl-Shift-Enter or Ctrl-S saves a draft.
$("#todo-form").addEventListener("keydown", (e) => {
  if (e.ctrlKey && e.key === "Enter") { e.preventDefault(); $("#todo-sheet").close(e.shiftKey ? "draft" : "queue"); }
  if (e.ctrlKey && e.key.toLowerCase() === "s") { e.preventDefault(); $("#todo-sheet").close("draft"); }
});

